import { test, expect } from '@playwright/test';

/**
 * Regression guard for the setup dead-end fix: a member (or any non-owner/admin) can't complete
 * the required LLM step, so they must never be trapped on /setup. The SetupWizard redirects
 * non-admins to /dashboard; the layout gate doesn't force them there. Owners/admins keep access.
 *
 * Persona-aware (runs under the audit config's admin/member/free projects).
 */
test('setup route is gated to owners/admins', async ({ page }) => {
  const persona = test.info().project.name;
  await page.goto('/setup');
  // Give the client-side permission-gated redirect time to resolve.
  await page.waitForTimeout(4000);
  const path = new URL(page.url()).pathname;

  if (persona === 'admin') {
    // Owner/super-admin can complete setup → stays on /setup (not bounced to /dashboard).
    expect(path, 'admin should be able to open /setup').toBe('/setup');
  } else {
    // member / free (non-admin) → redirected off the un-completable wizard.
    expect(path, `${persona} should be redirected off /setup`).not.toBe('/setup');
  }
});

import { test as setup } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

const AUTH_DIR = path.join(__dirname, '../.auth');
fs.mkdirSync(AUTH_DIR, { recursive: true });

/**
 * Three personas for full-surface coverage. A large fraction of the UI is RBAC/tier gated
 * and *hidden* (not merely disabled), so one login can't reach every button/menu.
 *
 * - admin  — super-admin (bypasses RBAC): sees everything.
 * - member — plain org member (RBAC-gated): exercises hidden/denied paths.
 * - free   — free/billing-disabled surface. NOTE: Stripe is unconfigured locally, so
 *            `billingEnabled` is already false for every persona and the free-tier paywall
 *            can't be exercised without Stripe test keys. Until then `free` reuses the
 *            member login; the separate state file keeps the config stable for when billing
 *            is enabled. See dev/UI_UX_AUDIT.md.
 *
 * Creds via env, defaulting to the seeded users (e2e/seed-test-data.js).
 */
const PERSONAS = [
  { name: 'admin', email: process.env.E2E_ADMIN_EMAIL || 'test@test.com', password: process.env.E2E_ADMIN_PASSWORD || 'Test123!' },
  { name: 'member', email: process.env.E2E_MEMBER_EMAIL || 'jordan@acme.test', password: process.env.E2E_MEMBER_PASSWORD || 'Test123!' },
  { name: 'free', email: process.env.E2E_FREE_EMAIL || 'jordan@acme.test', password: process.env.E2E_FREE_PASSWORD || 'Test123!' },
];

for (const p of PERSONAS) {
  setup(`authenticate ${p.name}`, async ({ page }) => {
    setup.setTimeout(120_000); // cold webpack compile of /auth + post-login /dashboard is slow
    await page.goto('/auth/login');
    await page.waitForLoadState('networkidle');
    await page.getByPlaceholder('Email Address').fill(p.email);
    await page.getByPlaceholder('Password').fill(p.password);
    await page.getByRole('button', { name: /sign in/i }).click();
    // The backend replies with reload:true → the client reloads and redirects off /auth/login.
    // On a cold compile this can take a while; wait generously and don't fail the whole sweep.
    await page.waitForURL((u) => !u.toString().includes('/auth/login'), { timeout: 90_000 });
    await page.waitForLoadState('networkidle').catch(() => {});
    console.log(`[auth:${p.name}] ${p.email} → ${page.url()}`);
    await page.context().storageState({ path: path.join(AUTH_DIR, `${p.name}.json`) });
  });
}

import { test } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { ROUTES } from './lib/routes';
import { PageAuditor } from './lib/audit';
import { inventory, actionableSummary, dismissModal } from './lib/crawl';

/**
 * Actively EXERCISE each route (the crawler only inventories). Per route, non-destructively:
 *  - switch every tab and assert no console/page error,
 *  - open every "opener" control (add/new/create/configure/edit/open/filter/customize/invite/
 *    connect/upload/⋯) and assert the modal/menu MOUNTS without a console/page/API error,
 *  - inside an opened modal, if it has a submit + a required field, submit EMPTY and record
 *    whether it validated, errored uncaught, or silently succeeded (the "/setup Next" class),
 *  - then dismiss to a clean state.
 *
 * Destructive labels (delete/remove/revoke/logout/…) are skipped by safeClick semantics.
 * Findings are flagged, not asserted-fatal. Output: results-exercise-<persona>.json.
 */
const PERSONA = () => test.info().project.name || 'admin';

const OPENER = /add|new|create|configure|connect|edit|open|manage|invite|customize|filter|upload|settings|generate|import|\+/i;
const DESTRUCTIVE = /delete|remove|disconnect|revoke|cancel subscription|log ?out|sign ?out|deactivate|reset|clear|purge|archive|unpublish/i;
const SUBMIT = /save|submit|create|add|confirm|continue|next|send|apply|generate/i;

async function modalOpen(page: any): Promise<boolean> {
  const dialog = page.getByRole('dialog').first();
  if (await dialog.isVisible({ timeout: 300 }).catch(() => false)) return true;
  const bespoke = page.locator('[class*="modal" i], [data-modal], [role="dialog"]').first();
  return bespoke.isVisible({ timeout: 300 }).catch(() => false);
}

test('exercise menus, modals and forms on every route', async ({ page }) => {
  // Exercising every opener on every route runs past 10 minutes.
  test.setTimeout(900_000);
  const persona = PERSONA();
  const auditor = new PageAuditor(page).attach();
  const findings: any[] = [];

  for (const route of ROUTES) {
    if (route.publicRoute) continue; // auth/share flows exercised separately
    const f: any = { name: route.name, path: route.path, persona, area: route.area, actions: [], flags: [] };

    try {
      await page.goto(route.path, { timeout: 30_000 });
      await page.waitForLoadState('networkidle', { timeout: 12_000 }).catch(() => {});
      await page.waitForTimeout(700);
    } catch (e: any) {
      f.flags.push('NAV_ERROR: ' + String(e.message).slice(0, 60));
      findings.push(f);
      continue;
    }
    if (/\/auth\//.test(page.url())) { f.skipped = 'redirected-to-auth'; findings.push(f); continue; }

    const items = await inventory(page);
    f.summary = actionableSummary(items);

    // ---- Tabs: switching should never throw ----
    const tabLabels = [...new Set(items.filter((i) => i.role === 'tab' && i.visible && i.enabled && i.label).map((i) => i.label))].slice(0, 12);
    for (const label of tabLabels) {
      auditor.reset();
      const tab = page.getByRole('tab', { name: label }).first();
      if (!(await tab.isVisible().catch(() => false))) continue;
      await tab.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(400);
      const s = auditor.snapshot();
      const bad = [...s.pageErrors, ...s.apiErrors.filter((e) => e.status >= 500).map((e) => e.url)];
      if (bad.length) f.flags.push(`TAB_ERROR[${label}]: ${bad.slice(0, 2).join(' | ')}`);
    }

    // ---- Openers: modals/menus should mount cleanly ----
    const openers = [...new Set(
      items.filter((i) => (i.role === 'button' || i.role === 'link') && i.visible && i.enabled && i.label && OPENER.test(i.label) && !DESTRUCTIVE.test(i.label)).map((i) => i.label)
    )].slice(0, 18);

    for (const label of openers) {
      auditor.reset();
      const el = page.getByRole('button', { name: label }).first();
      if (!(await el.isVisible({ timeout: 500 }).catch(() => false))) continue;
      const before = page.url();
      await el.click({ timeout: 4000 }).catch(() => {});
      await page.waitForTimeout(600);
      const opened = await modalOpen(page);
      const s = auditor.snapshot();
      const action: any = { label, opened, navigated: page.url() !== before };
      const serverErr = s.apiErrors.filter((e) => e.status >= 500);
      if (s.pageErrors.length) { action.pageError = s.pageErrors[0]; f.flags.push(`OPEN_PAGEERROR[${label}]: ${s.pageErrors[0].slice(0, 60)}`); }
      if (serverErr.length) { action.api5xx = serverErr.map((e) => e.status + ' ' + e.url); f.flags.push(`OPEN_5XX[${label}]: ${serverErr[0].status} ${serverErr[0].url}`); }

      // ---- Invalid submit probe inside an opened modal ----
      if (opened) {
        const submit = page.getByRole('button', { name: SUBMIT }).last();
        const hasReq = await page.locator('[required], [aria-required="true"]').first().isVisible({ timeout: 300 }).catch(() => false);
        if (hasReq && (await submit.isVisible({ timeout: 300 }).catch(() => false)) && (await submit.isEnabled().catch(() => false))) {
          auditor.reset();
          const urlBefore = page.url();
          await submit.click({ timeout: 3000 }).catch(() => {});
          await page.waitForTimeout(500);
          const s2 = auditor.snapshot();
          const invalidShown = await page.locator('[aria-invalid="true"], .text-red-500, [class*="error" i]').first().isVisible({ timeout: 300 }).catch(() => false);
          const stillOpen = await modalOpen(page);
          if (s2.pageErrors.length) f.flags.push(`INVALID_SUBMIT_PAGEERROR[${label}]: ${s2.pageErrors[0].slice(0, 50)}`);
          else if (s2.apiErrors.some((e) => e.status >= 500)) f.flags.push(`INVALID_SUBMIT_5XX[${label}]`);
          else if (!invalidShown && !stillOpen && page.url() === urlBefore) f.flags.push(`INVALID_SUBMIT_NO_VALIDATION[${label}] (empty form accepted?)`);
          action.invalidSubmit = { invalidShown, stillOpen };
        }
      }

      f.actions.push(action);
      await dismissModal(page);
      // If the opener navigated away, return to the route for the next probe.
      if (page.url() !== before && !/\/auth\//.test(page.url())) {
        await page.goto(route.path, { timeout: 20_000 }).catch(() => {});
        await page.waitForTimeout(400);
      }
    }

    findings.push(f);
  }

  auditor.detach();
  fs.writeFileSync(path.join(__dirname, `../results-exercise-${persona}.json`), JSON.stringify({ persona, findings }, null, 2));

  const flagged = findings.filter((f) => f.flags.length);
  console.log(`\n=== EXERCISE (${persona}) ===`);
  for (const f of flagged) {
    console.log(`⚠️  ${f.name.padEnd(22)} ${String(f.path).slice(0, 28).padEnd(28)} ${f.flags.length} flags`);
    for (const flag of f.flags.slice(0, 5)) console.log(`      🚩 ${flag}`);
  }
  console.log(`\n${flagged.length}/${findings.length} routes flagged. Full: results-exercise-${persona}.json`);
});

import { describe, it, expect } from 'vitest';
import { emphasise, emphasisTokens } from './rich-text';

const style = { fontWeight: 900, fill: '#ff5a36' };

describe('emphasise', () => {
  it('sets the offer apart from the words around it', () => {
    const runs = emphasise('Half price this week', ['Half price'], style)!;
    expect(runs.map((r) => r.text)).toEqual(['Half price', ' this week']);
    expect(runs[0].fontWeight).toBe(900);
    expect(runs[1].fontWeight).toBeUndefined();
  });

  it('keeps the headline′s own casing, not the token′s', () => {
    // A preset with `headlineTransform: 'uppercase'` has already decided the
    // case; substituting the token would undo it mid-line.
    const runs = emphasise('HALF PRICE THIS WEEK', ['half price'], style)!;
    expect(runs[0].text).toBe('HALF PRICE');
  });

  it('emphasises every occurrence', () => {
    const runs = emphasise('Free coffee, free cake', ['free'], style)!;
    expect(runs.filter((r) => r.fontWeight).map((r) => r.text)).toEqual(['Free', 'free']);
  });

  it('prefers the more specific token when two overlap', () => {
    // "40% off" is the offer; "40%" alone is half of it.
    const runs = emphasise('Get 40% off today', ['40%', '40% off'], style)!;
    expect(runs.find((r) => r.fontWeight)!.text).toBe('40% off');
  });

  it('handles a token at the very start and the very end', () => {
    expect(emphasise('Free delivery', ['Free'], style)!.map((r) => r.text)).toEqual([
      'Free',
      ' delivery',
    ]);
    expect(emphasise('Delivery free', ['free'], style)!.map((r) => r.text)).toEqual([
      'Delivery ',
      'free',
    ]);
  });

  it('returns null when nothing matched, so the caller keeps a plain string', () => {
    // `_clampTextToFit` skips any element carrying `richText`, so a pointless
    // single-run one would silently opt the headline out of overflow correction.
    expect(emphasise('Nothing to see', ['40%'], style)).toBeNull();
  });

  it('returns null when EVERY run would be emphasised', () => {
    // The contrast is what carries the meaning; a headline entirely in the
    // accent has no emphasis at all.
    expect(emphasise('Free', ['Free'], style)).toBeNull();
  });

  it('returns null when there is no emphasis to apply', () => {
    expect(emphasise('Half price this week', ['Half price'], {})).toBeNull();
  });

  it('ignores empty and one-character tokens', () => {
    expect(emphasise('Half price', ['', ' ', 'a'], style)).toBeNull();
  });

  it('treats a token with regex characters as literal text', () => {
    // "$19.99" is full of metacharacters; unescaped it would match almost
    // anything, or throw.
    const runs = emphasise('Only $19.99 today', ['$19.99'], style)!;
    expect(runs.find((r) => r.fontWeight)!.text).toBe('$19.99');
  });

  it('handles empty copy', () => {
    expect(emphasise('', ['free'], style)).toBeNull();
    expect(emphasise('   ', ['free'], style)).toBeNull();
  });
});

describe('emphasisTokens', () => {
  it('finds the promotional figure a headline exists for', () => {
    expect(emphasisTokens('Get 40% off everything')).toEqual(['40% off']);
    expect(emphasisTokens('Now only £20')).toEqual(['£20']);
    // The token keeps the headline's own casing — it is matched FROM the
    // headline, so it can be handed straight back to `emphasise`.
    expect(emphasisTokens('Half price this week')).toEqual(['Half price']);
  });

  it('finds multi-buy offers', () => {
    expect(emphasisTokens('2 for 1 on all bags')).toEqual(['2 for 1']);
  });

  it('returns at most one, because two emphases are none', () => {
    expect(emphasisTokens('Free delivery and 40% off').length).toBe(1);
  });

  it('finds nothing in an ordinary headline', () => {
    // Emphasising an arbitrary word is decoration, not hierarchy.
    expect(emphasisTokens('Our new autumn collection')).toEqual([]);
  });

  it('prefers the longest match', () => {
    expect(emphasisTokens('Save 40% off now')[0]).toBe('40% off');
  });
});

import { describe, expect, it } from 'vitest';
import { buildBadgePlate } from './badge-plate';

const BOX = { x: 100, y: 200, width: 300, height: 60 };
const CANVAS = { w: 1080, h: 1080 };

describe('buildBadgePlate', () => {
  it('builds a pill as a rect with a half-height radius', () => {
    const plate = buildBadgePlate(BOX, 'pill', '#C0392B', CANVAS, 'badge') as any;
    expect(plate.type).toBe('shape');
    expect(plate.shape).toBe('rect');
    expect(plate.x).toBe(100);
    expect(plate.width).toBe(300);
    expect(plate.borderRadius).toBe(30);
    expect(plate.originId).toBe('badge-bg');
    expect(plate.groupId).toBe('badge');
  });

  it('honors a plan-authored borderRadius over the pill default', () => {
    const plate = buildBadgePlate(BOX, 'pill', '#C0392B', CANVAS, 'badge', {
      borderRadius: 8,
    }) as any;
    expect(plate.borderRadius).toBe(8);
  });

  it('builds a ribbon as a closed canvas-box path whose edges bow the SAME way', () => {
    const plate = buildBadgePlate(BOX, 'ribbon', '#C0392B', CANVAS, 'badge') as any;
    expect(plate.type).toBe('path');
    expect(plate.closed).toBe(true);
    // Canvas box + absolute nodes — the emit-decor contract.
    expect(plate.x).toBe(0);
    expect(plate.width).toBe(CANVAS.w);
    expect(plate.originId).toBe('badge-bg');
    // The "1893 barrel" regression: both long edges must bow in the same
    // direction (control points above their anchors on top AND bottom), or
    // the band fattens into a lens instead of arching.
    const [topLeft, topRight, bottomRight, bottomLeft] = plate.nodes;
    expect(topLeft.outY).toBeLessThan(topLeft.y);
    expect(topRight.inY).toBeLessThan(topRight.y);
    expect(bottomRight.outY).toBeLessThan(bottomRight.y);
    expect(bottomLeft.inY).toBeLessThan(bottomLeft.y);
  });
});

import { describe, it, expect } from 'vitest';
import { isCatalogFamily } from '../../../media/designer-doc/font-catalog';
import { isScriptFamily, resolveFontFamily } from './resolve-font-family';

/**
 * Observed live in every reference run: the planner answers "what KIND of
 * face?" instead of naming one — `"script"` on the accent line, `"condensed"`
 * on a badge, `"serif"` on a subhead. Those went into the document verbatim
 * and painted in the fallback sans, which is why a poster's script accent
 * came out in Helvetica.
 */

describe('resolveFontFamily', () => {
  it('passes a real catalog family through untouched', () => {
    expect(resolveFontFamily('Playfair Display', 'Inter')).toBe('Playfair Display');
    expect(resolveFontFamily('Anton', 'Inter')).toBe('Anton');
  });

  it('maps the kind words the planner actually emits to loadable faces', () => {
    for (const kind of ['script', 'cursive', 'condensed', 'handwriting', 'brush', 'mono']) {
      const resolved = resolveFontFamily(kind, 'Inter');
      expect(resolved, kind).toBeTruthy();
      expect(isCatalogFamily(resolved!), `${kind} -> ${resolved}`).toBe(true);
      expect(resolved, kind).not.toBe(kind);
    }
  });

  it('prefers the formal copperplate for a script accent', () => {
    // The register reference posters reach for; the brush faces are the
    // fallbacks behind it.
    expect(resolveFontFamily('script', 'Inter')).toBe('Great Vibes');
  });

  it('treats generic kinds as "whatever the preset uses"', () => {
    expect(resolveFontFamily('serif', 'Playfair Display')).toBe('Playfair Display');
    expect(resolveFontFamily('sans-serif', 'Inter')).toBe('Inter');
    expect(resolveFontFamily('body', 'Inter')).toBe('Inter');
  });

  it('is case- and separator-insensitive, as a model is', () => {
    expect(resolveFontFamily('Condensed Sans', 'Inter')).toBe(
      resolveFontFamily('condensed-sans', 'Inter')
    );
    expect(resolveFontFamily('SCRIPT', 'Inter')).toBe('Great Vibes');
  });

  it('falls back rather than shipping a hallucinated family', () => {
    expect(resolveFontFamily('Helvetica Neue Ultra Whatever', 'Inter')).toBe('Inter');
    expect(resolveFontFamily('', 'Inter')).toBe('Inter');
    expect(resolveFontFamily(undefined, 'Inter')).toBe('Inter');
  });

  it('every mapped candidate is a family the loader can actually fetch', () => {
    // The mapping is only useful if the faces exist — this is the drift guard
    // for the table itself.
    for (const kind of ['script', 'condensed', 'condensed-serif', 'slab', 'display', 'mono']) {
      expect(isCatalogFamily(resolveFontFamily(kind, 'Inter')!), kind).toBe(true);
    }
  });
});

describe('isScriptFamily', () => {
  it('knows the faces an all-caps transform destroys', () => {
    for (const family of ['Great Vibes', 'Dancing Script', 'Pacifico', 'Caveat', 'Lobster']) {
      expect(isScriptFamily(family), family).toBe(true);
    }
  });

  it('leaves everything else alone', () => {
    for (const family of ['Anton', 'Inter', 'Playfair Display', 'Barlow Condensed', undefined]) {
      expect(isScriptFamily(family), String(family)).toBe(false);
    }
  });
});

import { describe, it, expect, vi } from 'vitest';
import path from 'path';
import { approximateAdvance, createTextMeasurer, forFace } from './measure-text';
import { wrapTextLines } from '../../../media/designer-doc/fit-text';

/** A font file committed to this repo, so the "registered face" half of the
 * contract is assertable on any machine and in CI, not only where system
 * fonts happen to exist. */
const PROBE_FONT_FILE = path.resolve(
  __dirname,
  '../../../../../../apps/frontend/public/fonts/WendyOne-Regular.ttf'
);

/**
 * The measurement the layout pass runs on.
 *
 * What matters here is not exact glyph widths — those are the font's business —
 * but that the measurer is synchronous, distinguishes faces, and degrades
 * rather than failing when canvas is unavailable.
 */

describe('createTextMeasurer', () => {
  it('returns a synchronous function, so the layout engine stays pure', async () => {
    // The whole reason this module exists: one await at the top, none below it.
    const measure = await createTextMeasurer();
    expect(measure('Hello', 48)).toBeTypeOf('number');
  });

  it('measures wider strings as wider', async () => {
    const measure = await createTextMeasurer();
    expect(measure('Half price this week', 48)).toBeGreaterThan(measure('Sale', 48));
  });

  it('scales with the font size', async () => {
    const measure = await createTextMeasurer();
    expect(measure('Sale', 96)).toBeGreaterThan(measure('Sale', 24));
  });

  it('measures empty text as nothing', async () => {
    const measure = await createTextMeasurer();
    expect(measure('', 48)).toBe(0);
  });

  it('distinguishes faces, which one constant for every family could not', async () => {
    // The defect this replaces: Anton is heavily condensed and Playfair is wide,
    // and the old estimate assumed they were the same width per character.
    const measure = await createTextMeasurer();
    const condensed = measure('HALF PRICE', 96, { fontFamily: 'Anton' });
    const wide = measure('HALF PRICE', 96, { fontFamily: 'Playfair Display' });
    // Both may resolve to a fallback face in a bare environment; assert only
    // that the measurer is asked to tell them apart, not that a font exists.
    expect(condensed).toBeGreaterThan(0);
    expect(wide).toBeGreaterThan(0);
  });

  it('falls back to the estimate for a face that was never registered', async () => {
    // CI caught this: node-canvas substitutes the platform's default sans for
    // an unregistered family WITHOUT saying so, so the same design measured
    // 36px wider on Linux than on macOS, and CTA plates were sized for a face
    // the renderer would never paint. An absent face must measure as the
    // documented estimate — one answer, the same everywhere.
    const measure = await createTextMeasurer();
    const text = 'Shop the sale';
    expect(measure(text, 48, { fontFamily: 'Anton' })).toBe(
      approximateAdvance(text, 48)
    );
    expect(measure(text, 48, { fontFamily: 'Definitely Not Installed' })).toBe(
      approximateAdvance(text, 48)
    );
  });

  it('uses real metrics once a face IS registered', async () => {
    // The other half of the contract: the fallback must not swallow a font
    // that genuinely loaded, or measuring would have been pointless.
    const { registerFont } = await import('canvas');
    registerFont(PROBE_FONT_FILE, { family: 'PostmillProbeFace' });
    const measure = await createTextMeasurer();
    const text = 'Shop the sale';
    expect(measure(text, 48, { fontFamily: 'PostmillProbeFace' })).not.toBe(
      approximateAdvance(text, 48)
    );
  });

  it('awaits the font load before measuring', async () => {
    const loadFonts = vi.fn(async () => {});
    await createTextMeasurer(loadFonts);
    expect(loadFonts).toHaveBeenCalledOnce();
  });

  it('degrades to the approximation when font loading throws', async () => {
    // The composer runs where canvas may not be built. A design laid out with
    // estimated metrics beats no design.
    const measure = await createTextMeasurer(async () => {
      throw new Error('no fonts');
    });
    expect(measure('Sale', 48)).toBe(approximateAdvance('Sale', 48));
  });

  it('never returns zero for non-empty text', async () => {
    // A family that failed to register measures as the fallback face — silently
    // wrong. Zero is the one answer that cannot be right, and it would collapse
    // every box the layout derives from it.
    const measure = await createTextMeasurer();
    for (const text of ['a', 'Half price', '40% off', '—', '☕']) {
      expect(measure(text, 48), text).toBeGreaterThan(0);
    }
  });

  it('caches, since the engine measures the same string at the same size repeatedly', async () => {
    const measure = await createTextMeasurer();
    const first = measure('Half price this week', 48);
    expect(measure('Half price this week', 48)).toBe(first);
  });
});

describe('forFace', () => {
  it('binds a face into the narrower signature fit-text expects', async () => {
    const measure = await createTextMeasurer();
    const bound = forFace(measure, { fontFamily: 'Inter', fontWeight: 700 });
    expect(bound('Sale', 48)).toBe(measure('Sale', 48, { fontFamily: 'Inter', fontWeight: 700 }));
  });

  it('drives real wrapping, which is the point of measuring at all', async () => {
    // Line count decides block height, which decides whether copy fits. This is
    // the chain the old approximation got wrong.
    const measure = await createTextMeasurer();
    const bound = forFace(measure, { fontFamily: 'Inter' });
    const narrow = wrapTextLines('Half price on every single-origin bag this week', 200, 32, 0, bound);
    const wide = wrapTextLines('Half price on every single-origin bag this week', 900, 32, 0, bound);
    expect(narrow.length).toBeGreaterThan(wide.length);
  });
});

describe('approximateAdvance', () => {
  it('is the old estimate, kept as the degraded path rather than the default', () => {
    expect(approximateAdvance('Sale', 100)).toBeCloseTo(4 * 100 * 0.56, 6);
  });
});

import { describe, it, expect } from 'vitest';
import { AiDesignerComposerService } from './ai-designer-composer.service';

/**
 * Observed live: a revision that said "set the Fresh & Tasty textScaleX to
 * 0.62" came back with the ACCENT line deleted — a whole line of the poster's
 * type stack gone from an instruction that named a different element, with
 * nothing in the UI to say so. Copy is now protected the way imagery already
 * was: a revise may only delete a line the user asked to delete.
 */

const svc = () => new AiDesignerComposerService({} as never, {} as never, {} as never);

const doc = (): any => ({
  version: 2,
  mode: 'image',
  outputs: [
    {
      id: 'o1',
      formatId: 'ig-post',
      name: 'Square',
      width: 1080,
      height: 1080,
      background: '#111',
      children: [
        { id: 'e-accent', originId: 'accent', type: 'text', text: 'Italian', x: 0, y: 0, width: 400, height: 90, rotation: 0, opacity: 1, locked: false, hidden: false },
        { id: 'e-head', originId: 'headline', type: 'text', text: 'PIZZA', x: 0, y: 100, width: 600, height: 160, rotation: 0, opacity: 1, locked: false, hidden: false },
        { id: 'e-img', originId: 'image', type: 'image', src: 'https://x/y.png', x: 0, y: 0, width: 1080, height: 1080, rotation: 0, opacity: 1, locked: false, hidden: false },
      ],
    },
  ],
});

const removeOp = (elementId: string) => ({ op: 'removeElement', outputIndex: 0, elementId } as never);
const filter = (ops: unknown[], removalAsked: boolean, targetSlots?: string[]) =>
  (svc() as never as {
    _filterReviseOps: (
      d: unknown, o: unknown[], t?: string[], l?: Record<string, string>, r?: boolean, s?: string[]
    ) => unknown[];
  })._filterReviseOps(doc(), ops, undefined, undefined, removalAsked, targetSlots);

describe('revise copy guard', () => {
  it('refuses to delete copy the instruction never asked to remove', () => {
    expect(filter([removeOp('e-accent')], false)).toHaveLength(0);
  });

  it('allows the deletion when the user actually asked for one', () => {
    expect(filter([removeOp('e-accent')], true)).toHaveLength(1);
  });

  it('allows it when the instruction targeted that slot', () => {
    expect(filter([removeOp('e-accent')], false, ['accent'])).toHaveLength(1);
  });

  it('still protects imagery even when a removal was asked for', () => {
    expect(filter([removeOp('e-img')], true)).toHaveLength(0);
  });

  it('lets an empty text element go — there is no copy to lose', () => {
    const d = doc();
    d.outputs[0].children[0].text = '   ';
    const out = (svc() as never as { _filterReviseOps: (...a: unknown[]) => unknown[] })
      ._filterReviseOps(d, [removeOp('e-accent')], undefined, undefined, false, undefined);
    expect(out).toHaveLength(1);
  });
});

describe('addElement duplicate guard (raw ops)', () => {
  const addOp = (element: Record<string, unknown>) =>
    ({ op: 'addElement', outputIndex: 0, element } as never);

  it('skips an added element whose originId duplicates an existing slot', () => {
    // Live: the model layered a free-floating 64px "FREE" with
    // originId "headline" NEXT TO the real headline.
    const out = filter(
      [
        addOp({
          id: '', type: 'text', text: 'FREE', originId: 'headline',
          x: 621, y: 643, width: 405, height: 109, fontSize: 64,
          rotation: 0, opacity: 1, locked: false, hidden: false,
        }),
      ],
      false
    );
    expect(out).toHaveLength(0);
  });

  it('keeps an added element with a fresh originId', () => {
    const out = filter(
      [
        addOp({
          id: '', type: 'text', text: 'Terms apply', originId: 'legal',
          x: 54, y: 1000, width: 972, height: 20, fontSize: 12,
          rotation: 0, opacity: 1, locked: false, hidden: false,
        }),
      ],
      false
    );
    expect(out).toHaveLength(1);
  });
});

