import { describe, it, expect, vi } from 'vitest';
import {
  applyKnockouts,
  knockoutRequests,
  MAX_KNOCKOUTS_PER_DESIGN,
} from './subject-knockout';
import type { DesignerElement } from '../../../media/designer-doc/designer-doc.schema';
import type { DesignSlot } from '../../ai-designer.types';

const image = (id: string, over: Partial<DesignerElement> = {}): DesignerElement =>
  ({
    id,
    originId: id,
    type: 'image',
    x: 0,
    y: 0,
    width: 100,
    height: 100,
    rotation: 0,
    opacity: 1,
    locked: false,
    hidden: false,
    src: 'https://example.test/photo.jpg',
    ...over,
  }) as DesignerElement;

const slot = (id: string, mask?: string): DesignSlot => ({ id, role: 'image', kind: 'image', mask });

const deps = (over: Partial<Parameters<typeof applyKnockouts>[1]> = {}) => ({
  removeBackground: vi.fn(async () => 'https://provider.test/cut.png'),
  importFromUrl: vi.fn(async () => ({ path: 'https://ours.test/cut.png', id: 'f-cut' })),
  warn: vi.fn(),
  ...over,
});

describe('knockoutRequests', () => {
  it('finds the image slots that asked for a cut-out', () => {
    // The recipe has been returning `knockout: true` since the design language
    // landed and nothing consumed it.
    const requests = knockoutRequests(
      [slot('hero', 'subject-knockout'), slot('other', 'circle')],
      [image('hero'), image('other')]
    );
    expect(requests.map((r) => r.slot.id)).toEqual(['hero']);
  });

  it('ignores a slot with no mask at all', () => {
    expect(knockoutRequests([slot('hero')], [image('hero')])).toEqual([]);
  });

  it('ignores a knockout whose image never resolved', () => {
    // A knockout with no source is not a degraded design, it is a wasted call.
    expect(
      knockoutRequests([slot('hero', 'subject-knockout')], [image('hero', { src: undefined })])
    ).toEqual([]);
  });

  it('ignores a knockout with no element at all', () => {
    expect(knockoutRequests([slot('ghost', 'subject-knockout')], [])).toEqual([]);
  });
});

describe('applyKnockouts', () => {
  const requests = () => knockoutRequests([slot('hero', 'subject-knockout')], [image('hero')]);

  it('replaces the source with the stored cut-out', async () => {
    const d = deps();
    const patches = await applyKnockouts(requests(), d, 'org-1');
    expect(patches.get('hero')).toMatchObject({
      src: 'https://ours.test/cut.png',
      fileId: 'f-cut',
    });
    expect(d.removeBackground).toHaveBeenCalledWith('https://example.test/photo.jpg', 'org-1');
  });

  it('switches to contain, since a cut-out no longer fills its box', async () => {
    // `cover` would crop the subject to fill a box the transparency vacated.
    const patches = await applyKnockouts(requests(), deps());
    expect(patches.get('hero')!.fitMode).toBe('contain');
  });

  it('keeps the original reachable, because a knockout is a treatment', async () => {
    const patches = await applyKnockouts(requests(), deps());
    expect(patches.get('hero')!.originalSrc).toBe('https://example.test/photo.jpg');
  });

  it('brings the cut-out under our own storage', async () => {
    const d = deps();
    await applyKnockouts(requests(), d);
    expect(d.importFromUrl).toHaveBeenCalledWith('https://provider.test/cut.png', undefined);
  });

  it('falls back silently-but-logged when no provider answers', async () => {
    // The org may have no background-removal provider at all. A design with an
    // uncut photograph is the same design with less depth.
    const d = deps({ removeBackground: vi.fn(async () => undefined) });
    const patches = await applyKnockouts(requests(), d);
    expect(patches.size).toBe(0);
    expect(d.warn).toHaveBeenCalledWith(expect.stringContaining('unavailable'));
  });

  it('falls back when the cut-out cannot be stored', async () => {
    const d = deps({ importFromUrl: vi.fn(async () => undefined) });
    const patches = await applyKnockouts(requests(), d);
    expect(patches.size).toBe(0);
    expect(d.warn).toHaveBeenCalledWith(expect.stringContaining('could not be stored'));
  });

  it('never throws, whatever the provider does', async () => {
    // A design that threw is no design at all.
    const d = deps({
      removeBackground: vi.fn(async () => {
        throw new Error('budget exhausted');
      }),
    });
    await expect(applyKnockouts(requests(), d)).resolves.toBeInstanceOf(Map);
    expect(d.warn).toHaveBeenCalledWith(expect.stringContaining('budget exhausted'));
  });

  it('pays for at most one knockout per design', async () => {
    // Each is a real provider call, and two cut-out subjects is a collage.
    const many = knockoutRequests(
      [slot('a', 'subject-knockout'), slot('b', 'subject-knockout')],
      [image('a'), image('b')]
    );
    const d = deps();
    await applyKnockouts(many, d);
    expect(d.removeBackground).toHaveBeenCalledTimes(MAX_KNOCKOUTS_PER_DESIGN);
  });

  it('does nothing when nothing asked', async () => {
    const d = deps();
    expect((await applyKnockouts([], d)).size).toBe(0);
    expect(d.removeBackground).not.toHaveBeenCalled();
  });
});

import { describe, it, expect } from 'vitest';
import { applySlotRecipes, treatmentAdjustmentLayers } from '../../design-language';
import { wrapMoveUnitsInGroups } from '../../util/layer-groups';
import { DesignerDocStrictSchema } from '../../../media/designer-doc/designer-doc.schema';
import { buildLayerTree } from '../../../media/designer-doc/layer-tree';
import type { DesignerElement } from '../../../media/designer-doc/designer-doc.schema';

/**
 * The design language reaching a real document.
 *
 * The unit specs prove each recipe expands correctly; this proves the result is
 * something the renderers will accept and draw. A recipe that produces a
 * document the strict schema rejects takes the WHOLE compose down to the
 * fallback layout, so this is the boundary worth guarding.
 */

const PALETTE = ['#0b1020', '#f5f5f0', '#ff5a36'];

const image = (): DesignerElement =>
  ({
    id: 'img',
    type: 'image',
    originId: 'hero',
    groupId: 'hero-unit',
    x: 0,
    y: 0,
    width: 1080,
    height: 700,
    rotation: 0,
    opacity: 1,
    locked: false,
    hidden: false,
    src: 'https://example.test/a.jpg',
    fitMode: 'cover',
  }) as DesignerElement;

const headline = (): DesignerElement =>
  ({
    id: 'h',
    type: 'text',
    originId: 'headline',
    groupId: 'hero-unit',
    x: 60,
    y: 760,
    width: 960,
    height: 220,
    rotation: 0,
    opacity: 1,
    locked: false,
    hidden: false,
    text: 'Half price this week',
    fontSize: 96,
  }) as DesignerElement;

const docOf = (children: DesignerElement[]) => ({
  version: 6,
  mode: 'image' as const,
  outputs: [
    {
      id: 'o',
      formatId: 'square',
      name: 'S',
      width: 1080,
      height: 1080,
      background: '#ffffff',
      children,
    },
  ],
});

const compose = (
  slots: Record<string, Parameters<typeof applySlotRecipes>[0]>
): DesignerElement[] => {
  const built: DesignerElement[] = [];
  for (const el of [image(), headline()]) {
    const slot = slots[el.originId!] || {};
    const kind = el.type === 'image' ? 'image' : 'text';
    const basis = kind === 'text' ? el.fontSize! : Math.min(el.width, el.height);
    const next = {
      ...el,
      ...applySlotRecipes(slot, el, { basis, palette: PALETTE, kind }, el.text),
    } as DesignerElement;
    built.push(next);
    if (kind === 'image') {
      built.push(...treatmentAdjustmentLayers(slot, next, { palette: PALETTE }));
    }
  }
  return wrapMoveUnitsInGroups(built, { genId: () => 'grp-1' });
};

describe('a plan carrying the design language composes a valid document', () => {
  it('validates with effects, a treatment and a mask all applied', () => {
    const children = compose({
      hero: { treatment: 'duotone-brand', mask: 'arch' },
      headline: { effects: ['soft-lift', 'sticker-outline'] },
    });
    const parsed = DesignerDocStrictSchema.safeParse(docOf(children));
    expect(parsed.success, JSON.stringify(parsed.error?.issues?.[0])).toBe(true);
  });

  it('puts the adjustment layers directly above the image they grade', () => {
    // Order is the effect: an adjustment grades whatever is beneath it, so one
    // that drifted below its image would grade the background instead.
    const children = compose({ hero: { treatment: 'duotone-brand' } });
    const ids = children.map((c) => `${c.type}:${c.adjustment?.type ?? ''}`);
    const imageIndex = ids.findIndex((s) => s.startsWith('image'));
    const firstAdj = ids.findIndex((s) => s.startsWith('adjustment'));
    expect(firstAdj).toBe(imageIndex + 1);
  });

  it('clips the adjustments so they cannot grade the copy', () => {
    const children = compose({ hero: { treatment: 'mono-tint' } });
    const adjustments = children.filter((c) => c.type === 'adjustment');
    expect(adjustments.length).toBeGreaterThan(0);
    expect(adjustments.every((a) => a.clipped)).toBe(true);
  });

  it('keeps the adjustments inside the image′s folder', () => {
    // Otherwise a re-fit moves the image and leaves its grade behind.
    const children = compose({ hero: { treatment: 'mono' } });
    const tree = buildLayerTree(children);
    const group = tree.find((n) => n.element.type === 'group');
    expect(group).toBeDefined();
    const inside = group!.children.map((c) => c.element.type);
    expect(inside).toContain('adjustment');
    expect(inside).toContain('image');
  });

  it('leaves a plan with no design language exactly as it was', () => {
    // Every existing plan is one of these; the new vocabulary must be inert
    // when unused.
    const plain = compose({});
    expect(plain.filter((c) => c.type === 'adjustment')).toHaveLength(0);
    expect(plain.every((c) => c.styles === undefined)).toBe(true);
    expect(plain.every((c) => c.smartFilters === undefined)).toBe(true);
  });

  it('validates when every image recipe is stacked at once', () => {
    const children = compose({
      hero: { treatment: 'halftone-print', mask: 'squircle', effects: ['framed-plate'], blend: 'multiply' },
      headline: { effects: ['neon-glow'], rotation: -4 },
    });
    const parsed = DesignerDocStrictSchema.safeParse(docOf(children));
    expect(parsed.success, JSON.stringify(parsed.error?.issues?.[0])).toBe(true);
  });

  it('writes a filter recipe the server renderer can evaluate on its own', () => {
    // Smart filters are a recipe plus the pixels it starts from. The composer
    // has baked nothing, so `src` IS the original — and the server resolves
    // `originalSrc || src`, so this renders correctly either way.
    const children = compose({ hero: { treatment: 'film-grain' } });
    const img = children.find((c) => c.type === 'image')!;
    expect(img.smartFilters?.length).toBeGreaterThan(0);
    expect(img.src).toBeTruthy();
  });
});

import { describe, expect, it } from 'vitest';
import {
  defineLockup,
  instantiateLockup,
  lockupOverrideText,
  lockupSymbolId,
  LOCKUP_LABEL,
  LOCKUP_PLATE,
} from './lockups';
import { expandSymbols } from '../../../media/designer-doc/symbols';
import type { DesignerElement } from '../../../media/designer-doc/designer-doc.schema';

/**
 * The lockup contract: the instance IS the addressable unit. It keeps the
 * slot's originId, geometry lands on its box, and content/style land in
 * symbolOverrides keyed by the definition's child ids — so a CTA restyled on
 * one format is restyled on all thirty.
 */

const plate = (over: Partial<DesignerElement> = {}): DesignerElement =>
  ({
    id: '',
    type: 'shape',
    shape: 'rect',
    x: 434,
    y: 856,
    width: 213,
    height: 59,
    rotation: 0,
    opacity: 1,
    locked: false,
    hidden: false,
    fill: '#FF4D00',
    borderRadius: 8,
    groupId: 'cta',
    originId: 'cta-bg',
    ...over,
  }) as DesignerElement;

const label = (over: Partial<DesignerElement> = {}): DesignerElement =>
  ({
    id: '',
    type: 'text',
    x: 434,
    y: 856,
    width: 213,
    height: 59,
    rotation: 0,
    opacity: 1,
    locked: false,
    hidden: false,
    text: 'Shop the sale',
    fontSize: 28,
    fill: '#FFFFFF',
    align: 'center',
    groupId: 'cta',
    originId: 'cta',
    ...over,
  }) as DesignerElement;

describe('defineLockup', () => {
  it('re-roots the pair into symbol-local coordinates with fix-targetable ids', () => {
    const def = defineLockup('cta', plate(), label());
    expect(def.id).toBe(lockupSymbolId('cta'));
    expect(def.width).toBe(213);
    expect(def.height).toBe(59);
    const [p, l] = def.children;
    expect([p.id, l.id]).toEqual([LOCKUP_PLATE, LOCKUP_LABEL]);
    expect([p.x, p.y, l.x, l.y]).toEqual([0, 0, 0, 0]);
  });

  it('strips per-output addressing from the children — the instance is what you edit', () => {
    const def = defineLockup('cta', plate(), label());
    for (const child of def.children) {
      expect(child.originId).toBeUndefined();
      expect(child.groupId).toBeUndefined();
    }
  });
});

describe('instantiateLockup → expandSymbols round trip', () => {
  it('yields plate+label at the instance box with the override text applied', () => {
    const def = defineLockup('cta', plate(), label());
    const instance = instantiateLockup(def, {
      originId: 'cta',
      groupId: 'cta',
      box: { x: 100, y: 200, width: 213, height: 59 },
      overrides: { [LOCKUP_LABEL]: { text: 'Shop now' } },
    });

    const out = expandSymbols([instance], [def]);
    expect(out.map((el) => el.id)).toEqual([
      `${instance.id}::${LOCKUP_PLATE}`,
      `${instance.id}::${LOCKUP_LABEL}`,
    ]);
    expect(out[0]).toMatchObject({
      type: 'shape',
      x: 100,
      y: 200,
      width: 213,
      height: 59,
      fill: '#FF4D00',
    });
    expect(out[1]).toMatchObject({ type: 'text', x: 100, y: 200, text: 'Shop now' });
  });

  it('scales the children — fontSize included — from the instance box', () => {
    // Geometry operations patch the instance box only; the expansion scales
    // the lockup like a group, which is what makes refit/safe-zone clamps
    // work without knowing symbols exist.
    const def = defineLockup('cta', plate(), label());
    const instance = instantiateLockup(def, {
      originId: 'cta',
      box: { x: 0, y: 0, width: 426, height: 118 },
    });
    const out = expandSymbols([instance], [def]);
    expect(out[0].width).toBe(426);
    expect(out[1].fontSize).toBe(56);
  });

  it('namespaces two instances of the same definition so their ids never collide', () => {
    const def = defineLockup('cta', plate(), label());
    const first = instantiateLockup(def, {
      originId: 'cta',
      box: { x: 0, y: 0, width: 213, height: 59 },
    });
    const second = instantiateLockup(def, {
      originId: 'cta',
      box: { x: 0, y: 0, width: 213, height: 59 },
    });
    first.id = 'inst-a';
    second.id = 'inst-b';
    const ids = expandSymbols([first, second], [def]).map((el) => el.id);
    expect(new Set(ids).size).toBe(ids.length);
    expect(ids).toEqual([
      'inst-a::plate',
      'inst-a::label',
      'inst-b::plate',
      'inst-b::label',
    ]);
  });
});

describe('lockupOverrideText', () => {
  it('reads the label an instance stands in for', () => {
    const def = defineLockup('cta', plate(), label());
    const instance = instantiateLockup(def, {
      originId: 'cta',
      box: { x: 0, y: 0, width: 213, height: 59 },
      overrides: { [LOCKUP_LABEL]: { text: 'Shop now' } },
    });
    expect(lockupOverrideText(instance)).toBe('Shop now');
  });

  it('is undefined for non-symbols and override-less instances', () => {
    expect(lockupOverrideText(label())).toBeUndefined();
    expect(
      lockupOverrideText({ type: 'symbol', symbolOverrides: {} } as never)
    ).toBeUndefined();
  });
});

