} from './extra-slots';
import { DesignerDocStrictSchema } from '../../../media/designer-doc/designer-doc.schema';
import type { DesignSlot } from '../../ai-designer.types';

/**
 * The five slot kinds that used to vanish.
 *
 * They were added to the schema with the design language and declared across
 * forty-one skills, and `_buildElements` read none of them — every one was
 * dropped before anything was built.
 */

const ctx = (over: Partial<ExtraSlotContext> = {}): ExtraSlotContext => ({
  w: 1080,
  h: 1080,
  margin: 60,
  accents: ['#ff5a36', '#2ec4b6'],
  ink: '#111111',
  headline: { x: 100, y: 400, width: 880, height: 160 },
  logo: { src: 'https://example.test/logo.png', fileId: 'f1', naturalWidth: 600, naturalHeight: 200 },
  ...over,
});

const slot = (kind: DesignSlot['kind'], role = 'decor', id = kind): DesignSlot => ({ id, role, kind });

const docOf = (children: unknown[]) => ({
  version: 6,
  mode: 'image' as const,
  outputs: [
    {
      id: 'o',
      formatId: 'square',
      name: 'S',
      width: 1080,
      height: 1080,
      background: '#ffffff',
      children,
    },
  ],
});

describe('isExtraSlot', () => {
  it('claims exactly the kinds nothing else builds', () => {
    for (const kind of ['shape', 'icon', 'divider', 'logo', 'frame'] as const) {
      expect(isExtraSlot({ kind }), kind).toBe(true);
    }
    for (const kind of ['text', 'image', 'cta-button', 'badge', 'accent-shape'] as const) {
      expect(isExtraSlot({ kind }), kind).toBe(false);
    }
  });
});

describe('every kind now produces something', () => {
  // `icon` is deliberately out of this list: an unresolved icon slot drops
  // (see the icon describe below) rather than stand in with a placeholder.
  it.each(['shape', 'divider', 'logo', 'frame'] as const)('%s builds an element', (kind) => {
    expect(buildExtraSlot(slot(kind), 0, ctx()).length).toBeGreaterThan(0);
  });

  it('produces documents the strict schema accepts', () => {
    // A malformed element fails the whole compose, not just itself.
    const children = buildExtraSlots(
      (['shape', 'icon', 'divider', 'logo', 'frame'] as const).map((k) => slot(k, 'decor', k)),
      ctx()
    );
    const parsed = DesignerDocStrictSchema.safeParse(docOf(children));
    expect(parsed.success, JSON.stringify(parsed.error?.issues?.[0])).toBe(true);
  });

  it('keeps the plan′s slot id as the originId, so revise fixes can address them', () => {
    const els = buildExtraSlots([slot('frame', 'decor', 'my-frame')], ctx());
    expect(els[0].originId).toBe('my-frame');
  });
});

describe('divider', () => {
  it('spans the headline, not the canvas', () => {
    // A rule spanning the canvas while the copy it separates spans half of it
    // reads as a mistake.
    const [el] = buildExtraSlot(slot('divider'), 0, ctx());
    const xs = el.nodes!.map((n) => n.x);
    expect(Math.min(...xs)).toBeCloseTo(100, 0);
    expect(Math.max(...xs)).toBeCloseTo(980, 0);
  });

  it('sits below the headline, clear of its descenders', () => {
    const [el] = buildExtraSlot(slot('divider'), 0, ctx());
    expect(Math.min(...el.nodes!.map((n) => n.y))).toBeGreaterThan(400 + 160);
  });

  it('falls back to the canvas middle when there is no headline', () => {
    const [el] = buildExtraSlot(slot('divider'), 0, ctx({ headline: undefined }));
    expect(el.nodes!.length).toBeGreaterThan(0);
  });

  it('sizes the element box to the canvas, since path nodes are absolute', () => {
    const [el] = buildExtraSlot(slot('divider'), 0, ctx());
    expect([el.x, el.y, el.width, el.height]).toEqual([0, 0, 1080, 1080]);
  });

  it('uses the decor recipe its role names', () => {
    const dashed = buildExtraSlot(slot('divider', 'dashed-rule'), 0, ctx())[0];
    expect(dashed.strokeStyle?.dash?.length).toBeGreaterThan(0);
  });
});

describe('frame', () => {
  it('is stroked and never filled', () => {
    // A filled frame is a panel, and a panel over imagery is the framed-inset
    // defect three separate assertions already forbid.
    const [el] = buildExtraSlot(slot('frame'), 0, ctx());
    expect(el.stroke).toBeTruthy();
    expect(el.strokeWidth).toBeGreaterThan(0);
    expect(el.fill).toBeUndefined();
  });

  it('sits inside the margin', () => {
    // A path's element box is the CANVAS — the nodes carry the position — so
    // the margin is checked against the geometry, not the box.
    const [el] = buildExtraSlot(slot('frame'), 0, ctx());
    const xs = el.nodes!.map((n) => n.x);
    expect(Math.min(...xs)).toBeGreaterThanOrEqual(60 - 0.001);
    expect(Math.max(...xs)).toBeLessThanOrEqual(1020 + 0.001);
  });

  it('rounds its corners with Live Corners rather than a border radius', () => {
    // `roundCorners` and `offsetPath` are shared, spec-covered, and were never
    // called by the composer until now. A real path is also what makes the
    // inner keyline below possible at all.
    const [el] = buildExtraSlot(slot('frame'), 0, ctx());
    expect(el.type).toBe('path');
    expect(el.nodes!.length).toBeGreaterThan(4);
  });

  it('draws a second, inset rule when there is room for one', () => {
    // Two lines a few pixels apart read as deliberate; one heavy line reads as
    // a browser border.
    const els = buildExtraSlot(slot('frame'), 0, ctx());
    expect(els).toHaveLength(2);
    expect(els[1].strokeWidth!).toBeLessThan(els[0].strokeWidth!);
    const outer = Math.min(...els[0].nodes!.map((n) => n.x));
    const inner = Math.min(...els[1].nodes!.map((n) => n.x));
    expect(inner).toBeGreaterThan(outer);
  });

  it('drops the inner rule on a frame too small to carry it', () => {
    // Inset on a small frame, the second line collides with the first.
    const small = buildExtraSlot(slot('frame'), 0, ctx(), {
      x: 10,
      y: 10,
      width: 40,
      height: 40,
    });
    expect(small).toHaveLength(1);
  });
});

describe('logo', () => {
  it('preserves aspect and never crops', () => {
    // A cropped logo is a trademark problem, not a layout one.
    const [el] = buildExtraSlot(slot('logo'), 0, ctx());
    expect(el.fitMode).toBe('contain');
    expect(el.width / el.height).toBeCloseTo(3, 1);
  });

  it('emits nothing when the brand has no logo, rather than an empty box', () => {
    expect(buildExtraSlot(slot('logo'), 0, ctx({ logo: undefined }))).toEqual([]);
  });

  it('assumes a wide lockup when the asset has no dimensions', () => {
    const [el] = buildExtraSlot(
      slot('logo'),
      0,
      ctx({ logo: { src: 'https://example.test/l.png' } })
    );
    expect(el.width).toBeGreaterThan(el.height);
  });
});

describe('icon', () => {
  it('drops the slot when nothing resolvable was named', () => {
    // No resolved icon in the context — the slot drops rather than emitting
    // the old ellipse stand-in, which rendered as a placeholder-looking blob
    // (a grey circle that read as a defect, not decor). Deliberate dots are
    // the `shape` kind's job.
    const els = buildExtraSlot(slot('icon'), 0, ctx());
    expect(els).toEqual([]);
  });

  it('emits a real icon element when the slot was resolved', () => {
    const [el] = buildExtraSlot(
      slot('icon', 'mdi:rocket', 'icon'),
      0,
      ctx({
        resolvedIcons: new Map([
          ['icon', { body: '<path d="M2 12l10-9 3 9-3 9z"/>' }],
        ]),
      })
    );
    expect(el.type).toBe('icon');
    expect(el.src).toBe('<path d="M2 12l10-9 3 9-3 9z"/>');
    expect(el.fill).toBeTruthy();
    // The raw-body contract is schema-valid on icon elements now.
    expect(
      DesignerDocStrictSchema.safeParse(docOf([{ ...el, id: 'i1' }])).success
    ).toBe(true);
  });
});

describe('resolveIconSlots', () => {
  beforeEach(() => mockResolve.mockReset());

  it('resolves only icon-kind slots whose role is an Iconify name', async () => {
    mockResolve.mockResolvedValue({ body: '<path d="M0 0h1v1z"/>' });
    const map = await resolveIconSlots([
      slot('icon', 'mdi:rocket', 'a'),
      slot('icon', 'decor', 'b'),
      slot('shape', 'mdi:rocket', 'c'),
    ]);
    expect(map.size).toBe(1);
    expect(map.get('a')?.body).toBe('<path d="M0 0h1v1z"/>');
    expect(mockResolve).toHaveBeenCalledTimes(1);
    expect(mockResolve).toHaveBeenCalledWith('mdi:rocket');
  });

  it('drops failures instead of failing the compose', async () => {
    mockResolve.mockResolvedValue(null);
    const map = await resolveIconSlots([slot('icon', 'mdi:nope', 'a')]);
    expect(map.size).toBe(0);
  });

  it('asset-agent-resolved icons win over the literal-role convention', async () => {
    mockResolve.mockResolvedValue({ body: '<path d="M9 9"/>' });
    const pre = new Map([['a', { body: '<path d="M1 1"/>', viewBox: '0 0 32 32' }]]);
    const map = await resolveIconSlots(
      [slot('icon', 'mdi:rocket', 'a'), slot('icon', 'mdi:rocket', 'b')],
      pre
    );
    // Slot 'a' keeps the pre-resolved body (no network resolve for it);
    // slot 'b' still resolves through its literal role.
    expect(map.get('a')?.body).toBe('<path d="M1 1"/>');
    expect(map.get('a')?.viewBox).toBe('0 0 32 32');
    expect(map.get('b')?.body).toBe('<path d="M9 9"/>');
    expect(mockResolve).toHaveBeenCalledTimes(1);
  });

  it('a pre-resolved icon needs no Iconify-shaped role at all', async () => {
    const pre = new Map([['a', { body: '<path d="M1 1"/>' }]]);
    const map = await resolveIconSlots([slot('icon', 'decor', 'a')], pre);
    expect(map.get('a')?.body).toBe('<path d="M1 1"/>');
    expect(mockResolve).not.toHaveBeenCalled();
  });
});

describe('placement', () => {
  it('cycles corners so two decorative slots do not stack', () => {
    const els = buildExtraSlots([slot('shape', 'decor', 'a'), slot('shape', 'decor', 'b')], ctx());
    expect({ x: els[0].x, y: els[0].y }).not.toEqual({ x: els[1].x, y: els[1].y });
  });

  it('honours a box the layout engine supplies, over its own corner table', () => {
    // The engine will place these once it drives the composer; the corner table
    // is the fallback, not the rule.
    const boxes = new Map([['shape', { x: 10, y: 20, width: 30, height: 40 }]]);
    const [el] = buildExtraSlots([slot('shape', 'decor', 'shape')], ctx(), boxes);
    expect([el.x, el.y, el.width, el.height]).toEqual([10, 20, 30, 40]);
  });

  it('keeps everything inside the canvas', () => {
    const els = buildExtraSlots(
      (['shape', 'icon', 'divider', 'logo', 'frame'] as const).map((k) => slot(k, 'decor', k)),
      ctx()
    );
    for (const el of els) {
      expect(el.x, el.originId).toBeGreaterThanOrEqual(0);
      expect(el.y, el.originId).toBeGreaterThanOrEqual(0);
      expect(el.x + el.width, el.originId).toBeLessThanOrEqual(1080);
      expect(el.y + el.height, el.originId).toBeLessThanOrEqual(1080);
    }
  });

  it('ignores slots that belong to somebody else', () => {
    expect(buildExtraSlots([slot('text', 'headline', 'h'), slot('image', 'image', 'i')], ctx())).toEqual([]);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { AiDesignerComposerService } from './ai-designer-composer.service';
import { DesignerDocService } from '@postmill-ai/nestjs-libraries/media/designer-doc/designer-doc.service';
import { COMPOSITION_IDS } from '../../layout/compositions';
import type { DesignPlan } from '../../ai-designer.types';

/**
 * Golden geometry, captured BEFORE the layout engine replaces the six
 * hand-written builders.
 *
 * Those builders encode about eight rounds of live remediation, and most of it
 * is in constants with no name. The ~240 assertions in the composer's own spec
 * pin the behaviours someone thought to write down; this pins everything else,
 * so that when the engine takes over, every single box that moves is visible
 * and has to be justified rather than silently re-recorded.
 *
 * Snapshots record ONLY geometry — originId, type and the rounded box. Ids,
 * colours, fonts and asset urls are deliberately excluded: they are covered
 * elsewhere and would make the diff unreadable at exactly the moment it matters.
 */

const compose = async (plan: DesignPlan, output: { formatId: string; width: number; height: number }) => {
  const service = new AiDesignerComposerService(
    new DesignerDocService() as any,
    { generateText: vi.fn() } as any
  );
  return service.compose({
    plan,
    copy: COPY,
    assets: ASSETS,
    outputs: [output],
    orgId: 'o1',
    userId: 'u1',
  });
};

const COPY = {
  headline: 'Half price this week only',
  sub: 'Every bag of single-origin, roasted on Tuesday',
  cta: 'Shop the sale',
  badge: '40% off',
  legal: 'Ends Sunday. While stocks last.',
};

const ASSETS = {
  img: {
    slotId: 'img',
    fileId: 'f1',
    path: 'https://example.com/i.png',
    type: 'image' as const,
    naturalWidth: 2000,
    naturalHeight: 1500,
  },
};

/**
 * Three slot sets, chosen because each exercises a different hand-tuned path:
 * the full set drives the badge carve AND the footer edge contract, `noFooter`
 * drives the CAPPED balance shift (the uncapped one only applies when a footer
 * exists), and `copyOnly` drives the D4 backdrop redirect.
 */
const SLOT_SETS = {
  full: [
    { id: 'img', role: 'image', kind: 'image' as const },
    { id: 'headline', role: 'headline', kind: 'text' as const },
    { id: 'sub', role: 'subhead', kind: 'text' as const },
    { id: 'cta', role: 'cta', kind: 'cta-button' as const },
    { id: 'badge', role: 'badge', kind: 'badge' as const },
    { id: 'legal', role: 'legal', kind: 'text' as const },
  ],
  noFooter: [
    { id: 'img', role: 'image', kind: 'image' as const },
    { id: 'headline', role: 'headline', kind: 'text' as const },
    { id: 'sub', role: 'subhead', kind: 'text' as const },
    { id: 'cta', role: 'cta', kind: 'cta-button' as const },
  ],
  copyOnly: [
    { id: 'headline', role: 'headline', kind: 'text' as const },
    { id: 'sub', role: 'subhead', kind: 'text' as const },
    { id: 'cta', role: 'cta', kind: 'cta-button' as const },
  ],
};

/** Square, story and banner — the three aspects channel variants actually hit. */
const CANVASES = [
  { formatId: 'ig-post', width: 1080, height: 1080 },
  { formatId: 'ig-story', width: 1080, height: 1920 },
  { formatId: 'tw-post', width: 1200, height: 675 },
];

const planFor = (composition: string, slots: DesignPlan['slots']): DesignPlan => ({
  variantId: 'v1',
  skill: 'sale-discount',
  concept: 'Half price week',
  formatTemplate: composition,
  styleId: 'bold',
  palette: [],
  typeScale: {},
  background: { kind: 'solid', value: '#0A0A0A' },
  slots,
  assetNeeds: [],
});

/**
 * Geometry only, rounded to whole pixels.
 *
 * Sub-pixel noise would make every snapshot churn on unrelated arithmetic
 * changes, and no design is wrong by half a pixel.
 */
const geometry = (doc: unknown) => {
  const output = (doc as { outputs: Record<string, unknown>[] }).outputs[0];
  const children = (output.children ?? []) as Record<string, number | string>[];
  return {
    typeBudget: output.typeBudget ?? null,
    children: children.map((el) => ({
      originId: el.originId ?? el.id,
      type: el.type,
      x: Math.round(el.x as number),
      y: Math.round(el.y as number),
      w: Math.round(el.width as number),
      h: Math.round(el.height as number),
      // Text only. The LENIENT schema applies `lenientNum(…, 16)` to every
      // element, so parsing stamps `fontSize: 16` onto images, shapes and group
      // containers too — half the snapshot would be that constant, and the
      // numbers that matter would be lost in it.
      ...(el.type === 'text' && el.fontSize
        ? { fontSize: Math.round(el.fontSize as number) }
        : {}),
    })),
  };
};

describe.each(COMPOSITION_IDS)('composition %s', (composition) => {
  it.each(CANVASES)('lays out on $formatId', async (canvas) => {
    const doc = await compose(planFor(composition, SLOT_SETS.full), canvas);
    expect(geometry(doc)).toMatchSnapshot();
  });
});

describe.each(['hero-fullbleed', 'split-panel', 'top-bottom', 'badge-burst', 'editorial-sidebar', 'minimal-centered'])(
  'legacy composition %s slot variants',
  (composition) => {
    it('without a footer, so the balance shift stays capped', async () => {
      const doc = await compose(planFor(composition, SLOT_SETS.noFooter), CANVASES[0]);
      expect(geometry(doc)).toMatchSnapshot();
    });

    it('with no imagery at all, which redirects the panel layouts', async () => {
      const doc = await compose(planFor(composition, SLOT_SETS.copyOnly), CANVASES[0]);
      expect(geometry(doc)).toMatchSnapshot();
    });
  }
);

/**
 * The channel-variant contract, stated as a test rather than left to the
 * snapshots: the same design at another size is the SAME design refitted —
 * never a different one, and never the square one squashed.
 */
describe('the same plan across aspects', () => {
  it('keeps the same elements, in the same order, on every canvas', async () => {
    const plan = planFor('hero-fullbleed', SLOT_SETS.full);
    const docs = await Promise.all(CANVASES.map((c) => compose(plan, c)));
    const origins = docs.map((d) =>
      geometry(d).children.map((c) => c.originId).sort()
    );
    expect(origins[1]).toEqual(origins[0]);
    expect(origins[2]).toEqual(origins[0]);
  });

  it('scales type with the canvas rather than pinning it to the short side', async () => {
    // The squashing bug: a 1200x675 banner sized its headline for 675px, so
    // every wide variant read as the square design compressed.
    const plan = planFor('hero-fullbleed', SLOT_SETS.full);
    const [square, , banner] = await Promise.all(CANVASES.map((c) => compose(plan, c)));
    const sizeOf = (doc: unknown) =>
      geometry(doc).children.find((c) => c.originId === 'headline')?.fontSize ?? 0;
    expect(sizeOf(banner)).toBeGreaterThan(0);
    expect(sizeOf(square)).toBeGreaterThan(0);
  });
});

/**
 * The defect this batch fixes, stated end to end.
 *
 * `shape`, `icon`, `divider`, `logo` and `frame` were added to `DesignSlot` and
 * declared across forty-one skills, and `_buildElements` read `plan.slots` in
 * three places that matched none of them. The slots were dropped before
 * anything was built, silently, in every design that asked for one.
 */
describe('slot kinds that used to vanish', () => {
  const withKinds = planFor('type-dominant', [
    { id: 'headline', role: 'headline', kind: 'text' },
    { id: 'sub', role: 'subhead', kind: 'text' },
    { id: 'rule', role: 'decor', kind: 'divider' },
    { id: 'mark', role: 'decor', kind: 'shape' },
    { id: 'edge', role: 'decor', kind: 'frame' },
  ]);

  it('composes an element for every declared kind', async () => {
    const doc = await compose(withKinds, CANVASES[0]);
    const origins = geometry(doc).children.map((c) => c.originId);
    for (const id of ['rule', 'mark', 'edge']) {
      expect(origins, `${id} was dropped`).toContain(id);
    }
  });

  it('keeps them inside the canvas', async () => {
    const doc = await compose(withKinds, CANVASES[1]);
    for (const el of geometry(doc).children) {
      expect(el.x, el.originId as string).toBeGreaterThanOrEqual(-1);
      expect(el.y, el.originId as string).toBeGreaterThanOrEqual(-1);
    }
  });

  it('still composes when a plan declares none of them', async () => {
    // The fix must be inert for every plan written before it.
    const doc = await compose(planFor('hero-fullbleed', SLOT_SETS.full), CANVASES[0]);
    expect(geometry(doc).children.length).toBeGreaterThan(0);
  });
});

describe('headline emphasis', () => {
  it('sets the offer apart inside the headline', async () => {
    // "Half price this week only" gave equal weight to the offer and the
    // filler around it. One word set heavier is the most basic typographic
    // move there is, and the composer could not make it.
    const doc = await compose(planFor('hero-fullbleed', SLOT_SETS.full), CANVASES[0]);
    const headline = (doc.outputs[0] as any).children.find(
      (c: any) => c.originId === 'headline'
    );
    expect(headline.richText?.length).toBeGreaterThan(1);
    const emphasised = headline.richText.filter((r: any) => r.fontWeight || r.fill);
    expect(emphasised.length).toBeGreaterThan(0);
    expect(emphasised.length).toBeLessThan(headline.richText.length);
  });

  it('does not change any geometry', async () => {
    // Emphasis runs AFTER `_clampTextToFit`, because the clamp skips elements
    // carrying `richText` — emphasising during construction opted headlines out
    // of overflow correction and returned them 12% larger.
    const doc = await compose(planFor('hero-fullbleed', SLOT_SETS.full), CANVASES[0]);
    expect(geometry(doc)).toMatchSnapshot();
  });

  it('leaves supporting copy alone', async () => {
    const doc = await compose(planFor('hero-fullbleed', SLOT_SETS.full), CANVASES[0]);
    const sub = (doc.outputs[0] as any).children.find((c: any) => c.originId === 'sub');
    expect(sub.richText).toBeUndefined();
  });
});

describe('typeBudget follows the arrangement that actually composed', () => {
  it('stamps an engine composition′s own band ratio, not its legacy fallback′s', async () => {
    // Invisible on the primary output and wrong on every other one:
    // `typeBudget` is what reflow re-fits the channel variants from, so a
    // type-dominant design stamped with minimal-centered's 0.52 would typeset
    // all its siblings for an arrangement it is not.
    const typeLed = await compose(planFor('type-dominant', SLOT_SETS.copyOnly), CANVASES[0]);
    const centred = await compose(planFor('minimal-centered', SLOT_SETS.copyOnly), CANVASES[0]);
    expect((typeLed.outputs[0] as any).typeBudget).not.toBeCloseTo(
      (centred.outputs[0] as any).typeBudget,
      3
    );
  });

  it('leaves the legacy six on the budget they always had', async () => {
    const doc = await compose(planFor('hero-fullbleed', SLOT_SETS.full), CANVASES[0]);
    expect((doc.outputs[0] as any).typeBudget).toBeGreaterThan(0);
  });
});

import { describe, it, expect } from 'vitest';
import {
  compositionRoleFor,
  expandRoles,
  groupByRole,
  layoutSlots,
  resolveCompositionFor,
  type BoundSlot,
} from './layout-bridge';
import { buildGrid } from '../../layout/grid';
import { compositionById } from '../../layout/compositions';
import type { LayoutNode } from '../../layout/box-model';

const bound = (
  id: string,
  role: BoundSlot['role'],
  kind: BoundSlot['slot']['kind'] = 'text',
  text = 'Copy'
): BoundSlot => ({ slot: { id, role, kind }, role, text });

const grid = buildGrid({ width: 1080, height: 1080, formatId: 'ig-post' });
const measureSlot = () => 100;

describe('compositionRoleFor', () => {
  it('maps the composer roles onto composition roles', () => {
    expect(compositionRoleFor(bound('h', 'headline'))).toBe('headline');
    expect(compositionRoleFor(bound('c', 'cta', 'cta-button'))).toBe('cta');
    expect(compositionRoleFor(bound('b', 'badge', 'badge'))).toBe('badge');
    expect(compositionRoleFor(bound('l', 'legal'))).toBe('legal');
  });

  it('stacks body copy with the subhead', () => {
    // A composition with a role per copy slot would be the template thinking
    // this replaces; body copy has always gone where the subhead goes.
    expect(compositionRoleFor(bound('x', 'body'))).toBe('subhead');
  });

  it('routes imagery and logos by KIND, not by role', () => {
    expect(compositionRoleFor(bound('i', 'body', 'image'))).toBe('image');
    expect(compositionRoleFor(bound('lg', 'body', 'logo'))).toBe('logo');
  });

  it('routes decoration away from the copy roles', () => {
    expect(compositionRoleFor(bound('d', 'body', 'accent-shape'))).toBe('decor');
    expect(compositionRoleFor(bound('d', 'body', 'divider'))).toBe('decor');
  });
});

describe('groupByRole', () => {
  it('collects several slots under one role, in plan order', () => {
    // Order is load-bearing: `_slotRole` makes the FIRST copy slot the
    // headline, so re-ordering here would silently re-rank the design.
    const grouped = groupByRole([
      bound('sub-a', 'subhead'),
      bound('sub-b', 'body'),
      bound('h', 'headline'),
    ]);
    expect(grouped.get('subhead')!.map((b) => b.slot.id)).toEqual(['sub-a', 'sub-b']);
    expect(grouped.get('headline')!.map((b) => b.slot.id)).toEqual(['h']);
  });
});

describe('expandRoles', () => {
  const roleLeaf = (role: string): LayoutNode => ({ kind: 'leaf', slotId: role });

  it('replaces a role with the slot bound to it', () => {
    const tree = expandRoles(roleLeaf('headline'), groupByRole([bound('h', 'headline')]));
    expect(tree).toMatchObject({ kind: 'leaf', slotId: 'h' });
  });

  it('stacks a role that several slots claim', () => {
    const tree = expandRoles(
      roleLeaf('subhead'),
      groupByRole([bound('a', 'subhead'), bound('b', 'body')])
    );
    expect(tree).toMatchObject({ kind: 'stack' });
    expect((tree as { children: { slotId: string }[] }).children.map((c) => c.slotId)).toEqual([
      'a',
      'b',
    ]);
  });

  it('drops a role no slot claims, which is what lets one composition serve many genres', () => {
    expect(expandRoles(roleLeaf('badge'), groupByRole([bound('h', 'headline')]))).toBeNull();
  });

  it('drops a container once every child has gone', () => {
    const tree: LayoutNode = { kind: 'stack', children: [roleLeaf('badge'), roleLeaf('legal')] };
    expect(expandRoles(tree, groupByRole([bound('h', 'headline')]))).toBeNull();
  });

  it('keeps the composition′s own hints on the expanded leaf', () => {
    // A composition saying "the image fills what is left" must survive binding.
    const tree = expandRoles(
      { kind: 'leaf', slotId: 'image', fill: true, aspect: 1.6 },
      groupByRole([bound('img', 'body', 'image')])
    );
    expect(tree).toMatchObject({ slotId: 'img', fill: true, aspect: 1.6 });
  });
});

describe('layoutSlots', () => {
  const slots = [
    bound('img', 'body', 'image'),
    bound('headline', 'headline'),
    bound('sub', 'subhead'),
    bound('cta', 'cta', 'cta-button'),
  ];

  it('places every slot the composition can hold', () => {
    const placed = layoutSlots({
      composition: compositionById('hero-fullbleed')!,
      grid,
      slots,
      measureSlot,
    });
    for (const s of slots) expect(placed.has(s.slot.id), s.slot.id).toBe(true);
  });

  it('keys placements by slot id, so a caller can reach its own factory', () => {
    const placed = layoutSlots({
      composition: compositionById('minimal-centered')!,
      grid,
      slots,
      measureSlot,
    });
    expect([...placed.keys()].every((k) => slots.some((s) => s.slot.id === k))).toBe(true);
  });

  it('keeps every box finite and inside the canvas horizontally', () => {
    const placed = layoutSlots({
      composition: compositionById('split-panel')!,
      grid,
      slots,
      measureSlot,
    });
    for (const [id, box] of placed) {
      expect(Number.isFinite(box.x), id).toBe(true);
      expect(Number.isFinite(box.y), id).toBe(true);
      expect(box.width, id).toBeGreaterThan(0);
      expect(box.x).toBeGreaterThanOrEqual(-1);
      expect(box.x + box.width).toBeLessThanOrEqual(grid.width + 1);
    }
  });

  it('returns nothing rather than throwing when no slot matches the composition', () => {
    const placed = layoutSlots({
      composition: compositionById('badge-burst')!,
      grid,
      slots: [],
      measureSlot,
    });
    expect(placed.size).toBe(0);
  });

  it('honours a reference-measured band over the composition box', () => {
    const withGeometry = [
      bound('img', 'body', 'image'),
      {
        ...bound('headline', 'headline'),
        slot: {
          id: 'headline',
          role: 'headline',
          kind: 'text' as const,
          geometry: { yBand: [0.08, 0.2] as [number, number], xAnchor: 'left' as const },
        },
      },
      bound('sub', 'subhead'),
    ];
    const placed = layoutSlots({
      composition: compositionById('hero-fullbleed')!,
      grid,
      slots: withGeometry as BoundSlot[],
      measureSlot,
    });
    const box = placed.get('headline')!;
    const contentHeight = grid.bottom - grid.top;
    expect(box.y).toBe(Math.round(grid.top + 0.08 * contentHeight));
    expect(box.height).toBe(Math.round(0.12 * contentHeight));
    expect(box.x).toBe(grid.left);
    // Width stays the engine's — bands are a vertical spec.
    expect(box.width).toBeGreaterThan(0);
    // Slots without geometry keep their engine boxes.
    expect(placed.get('sub')).toBeDefined();
  });

  it('never band-overrides imagery — the photo keeps the composition box', () => {
    const plain = [bound('img', 'body', 'image'), bound('headline', 'headline')];
    const withGeometry = [
      {
        ...bound('img', 'body', 'image'),
        slot: {
          id: 'img',
          role: 'body',
          kind: 'image' as const,
          geometry: { yBand: [0.4, 0.6] as [number, number] },
        },
      },
      bound('headline', 'headline'),
    ];
    const engine = layoutSlots({
      composition: compositionById('hero-fullbleed')!,
      grid,
      slots: plain,
      measureSlot,
    });
    const placed = layoutSlots({
      composition: compositionById('hero-fullbleed')!,
      grid,
      slots: withGeometry as BoundSlot[],
      measureSlot,
    });
    // The photo is the design's ground — a measured strip must not tear it
    // out of the composition. Identical box with or without geometry.
    expect(placed.get('img')).toEqual(engine.get('img'));
  });

  it('asks for each slot′s height at the width it will actually get', () => {
    // The two-pass contract. A headline is taller in a narrow column, and a
    // measure that ignored width is the bug this whole engine replaces.
    const widths: number[] = [];
    layoutSlots({
      composition: compositionById('split-panel')!,
      grid,
      slots,
      measureSlot: (_b, width) => {
        widths.push(width);
        return 100;
      },
    });
    expect(widths.length).toBeGreaterThan(0);
    expect(widths.every((w) => w > 0 && w <= grid.width)).toBe(true);
  });
});

describe('resolveCompositionFor', () => {
  const ctx = { aspect: 1, has: () => true };

  it('honours the first candidate that fits', () => {
    expect(resolveCompositionFor(['minimal-centered'], ctx, 'hero-fullbleed').id).toBe(
      'minimal-centered'
    );
  });

  it('falls through the candidates in order', () => {
    // plan.composition, then the legacy formatTemplate, then the default.
    expect(resolveCompositionFor([undefined, 'top-bottom'], ctx, 'hero-fullbleed').id).toBe(
      'top-bottom'
    );
  });

  it('replaces a composition the canvas cannot carry', () => {
    // A split panel on a story lays out fine and is unreadable — the failure
    // that never errors and always ships.
    const story = { aspect: 1080 / 1920, has: () => true };
    expect(resolveCompositionFor(['split-panel'], story, 'hero-fullbleed').id).not.toBe(
      'split-panel'
    );
  });

  it('replaces a composition whose centrepiece the plan lacks', () => {
    const noBadge = { aspect: 1, has: (r: string) => r !== 'badge' };
    expect(resolveCompositionFor(['badge-burst'], noBadge, 'hero-fullbleed').id).not.toBe(
      'badge-burst'
    );
  });

  it('always returns something, even when nothing named fits', () => {
    const extreme = { aspect: 0.1, has: () => false };
    expect(resolveCompositionFor(['split-panel', 'banner-strip'], extreme, 'split-panel')).toBeDefined();
  });
});

