describe('AuthController — F1 behavioural tests', () => {
  describe('register respects DISABLE_REGISTRATION', () => {
    // canRegister is the real unit implementing DISABLE_REGISTRATION; exercise it directly
    // with a mocked OrganizationService so the env-var contract is asserted on real code.
    function makeAuthService(orgCount: number) {
      const organizationService = {
        getCount: vi.fn().mockResolvedValue(orgCount),
      };
      const service = new AuthService(
        {} as any,
        organizationService as any,
        {} as any,
        {} as any
      );
      return { service, organizationService };
    }

    it('allows registration when DISABLE_REGISTRATION is unset', async () => {
      delete process.env.DISABLE_REGISTRATION;
      const { service } = makeAuthService(5);
      await expect(service.canRegister('LOCAL')).resolves.toBe(true);
    });

    it('blocks LOCAL registration when DISABLE_REGISTRATION=true and an org already exists', async () => {
      process.env.DISABLE_REGISTRATION = 'true';
      const { service, organizationService } = makeAuthService(1);
      await expect(service.canRegister('LOCAL')).resolves.toBe(false);
      expect(organizationService.getCount).toHaveBeenCalled();
    });

    it('still allows the very first org (bootstrap) when DISABLE_REGISTRATION=true', async () => {
      process.env.DISABLE_REGISTRATION = 'true';
      const { service } = makeAuthService(0);
      await expect(service.canRegister('LOCAL')).resolves.toBe(true);
    });

    it('always allows GENERIC (SSO) registration regardless of DISABLE_REGISTRATION', async () => {
      process.env.DISABLE_REGISTRATION = 'true';
      const { service } = makeAuthService(10);
      await expect(service.canRegister('GENERIC')).resolves.toBe(true);
    });

    it('controller register returns 400 (no auth cookie) when registration is disabled', async () => {
      const { controller, authService } = makeController({
        authService: {
          routeAuth: vi.fn().mockRejectedValue(new Error('Registration is disabled')),
        } as any,
      });
      const res = mockResponse();

      await controller.register(
        { cookies: {} } as any,
        { provider: 'LOCAL', email: 'a@b.com' } as any,
        res,
        '1.2.3.4',
        'agent'
      );

      expect(res.status).toHaveBeenCalledWith(400);
      expect(res.send).toHaveBeenCalledWith('Registration failed');
      expect(res.cookie).not.toHaveBeenCalledWith('auth', expect.anything(), expect.anything());
    });
  });

  describe('login', () => {
    it('on success sets the auth cookie + reload header and returns login:true', async () => {
      const { controller, authService } = makeController({
        authService: {
          getOrgFromCookie: vi.fn().mockReturnValue(false),
          routeAuth: vi
            .fn()
            .mockResolvedValue({ jwt: 'jwt-token', refreshToken: 'refresh-token', addedOrg: false }),
        } as any,
      });
      const res = mockResponse();

      await controller.login(
        { cookies: {} } as any,
        { provider: 'LOCAL', email: 'a@b.com', password: 'pw' } as any,
        res,
        '1.2.3.4',
        'agent'
      );

      expect(authService.routeAuth).toHaveBeenCalled();
      expect(res.cookie).toHaveBeenCalledWith('auth', 'jwt-token', expect.any(Object));
      expect(res.cookie).toHaveBeenCalledWith('refresh_token', 'refresh-token', expect.any(Object));
      expect(res.header).toHaveBeenCalledWith('reload', 'true');
      expect(res.json).toHaveBeenCalledWith({ login: true });
    });

    it('on invalid credentials returns 400 and never sets an auth cookie', async () => {
      const { controller } = makeController({
        authService: {
          getOrgFromCookie: vi.fn().mockReturnValue(false),
          routeAuth: vi.fn().mockRejectedValue(new Error('Invalid user name or password')),
        } as any,
      });
      const res = mockResponse();

      await controller.login(
        { cookies: {} } as any,
        { provider: 'LOCAL', email: 'a@b.com', password: 'bad' } as any,
        res,
        '1.2.3.4',
        'agent'
      );

      expect(res.status).toHaveBeenCalledWith(400);
      expect(res.send).toHaveBeenCalledWith('Invalid credentials');
      expect(res.cookie).not.toHaveBeenCalledWith('auth', expect.anything(), expect.anything());
    });
  });

  describe('GET /providers', () => {
    it('delegates provider-list composition to AuthProviderManager', async () => {
      const { controller, authProviderManager } = makeController({
        authProviderManager: {
          getProviders: vi.fn().mockResolvedValue({
            providers: [{ provider: 'LOCAL', displayName: 'Email', version: 'v1', status: 'active' }],
          }),
        },
      });

      const result = await controller.getProviders();

      expect(authProviderManager.getProviders).toHaveBeenCalled();
      expect(result).toEqual({
        providers: [{ provider: 'LOCAL', displayName: 'Email', version: 'v1', status: 'active' }],
      });
    });
  });

  describe('POST /oauth/:provider/exists', () => {
    it('forwards code, redirect_uri and the callback state to AuthService.checkExists', async () => {
      const { controller, authService } = makeController({
        authService: {
          checkExists: vi.fn().mockResolvedValue({ token: 'provider-token' }),
        } as any,
      });
      const res = mockResponse();

      await controller.oauthExists(
        'code-1',
        'https://app.example.com/integrations/social/x',
        'login.nonce-123',
        'X',
        res,
        '1.2.3.4',
        'agent'
      );

      expect(authService.checkExists).toHaveBeenCalledWith(
        'X',
        'code-1',
        'https://app.example.com/integrations/social/x',
        'login.nonce-123'
      );
      expect(res.json).toHaveBeenCalledWith({ token: 'provider-token', emailRequired: undefined });
    });
  });

  describe('JWT verification pins HS256', () => {
    const secret = process.env.JWT_SECRET as string;

    it('accepts a valid HS256 token', () => {
      const token = jwt.sign({ id: 'u1' }, secret); // default HS256
      const decoded: any = AuthChecker.verifyJWT(token);
      expect(decoded.id).toBe('u1');
    });

    it('rejects an alg=none (unsigned) token', () => {
      const token = jwt.sign({ id: 'u1' }, '', { algorithm: 'none' as any });
      expect(() => AuthChecker.verifyJWT(token)).toThrow();
    });

    it('rejects a token signed with a non-HS256 algorithm (HS512)', () => {
      const token = jwt.sign({ id: 'u1' }, secret, { algorithm: 'HS512' });
      expect(() => AuthChecker.verifyJWT(token)).toThrow(/algorithm/i);
    });
  });

  describe('refresh-token rotation', () => {
    function makeAuthServiceWithUsers(users: any) {
      return new AuthService(users as any, {} as any, {} as any, {} as any);
    }

    it('rotates the session token and issues a fresh JWT on a valid refresh', async () => {
      const users = {
        findSessionByTokenHash: vi
          .fn()
          .mockResolvedValue({ id: 'sess-1', userId: 'u1', tokenHash: 'old-hash', revokedAt: null, expiresAt: new Date(Date.now() + 86400000) }),
        rotateSessionToken: vi.fn().mockResolvedValue(undefined),
        getUserById: vi.fn().mockResolvedValue({ id: 'u1', email: 'a@b.com' }),
      };
      const service = makeAuthServiceWithUsers(users);

      const result = await service.refreshAccessToken('the-refresh-token', '1.2.3.4', 'agent');

      expect(users.rotateSessionToken).toHaveBeenCalled();
      expect(result.jwt).toBeTruthy();
      // a brand-new opaque refresh token is minted (rotation), not the same one back
      expect(result.refreshToken).not.toBe('the-refresh-token');
    });

    it('on reuse of a rotated-out token, revokes the live session and throws', async () => {
      const users = {
        findSessionByTokenHash: vi.fn().mockResolvedValue(null),
        findSessionByPreviousTokenHash: vi
          .fn()
          .mockResolvedValue({ id: 'sess-reused', userId: 'u1', revokedAt: null }),
        revokeSession: vi.fn().mockResolvedValue(undefined),
      };
      const service = makeAuthServiceWithUsers(users);

      await expect(
        service.refreshAccessToken('a-rotated-out-token', '1.2.3.4', 'agent')
      ).rejects.toThrow(/reuse/i);
      expect(users.revokeSession).toHaveBeenCalledWith('u1', 'sess-reused');
    });

    it('controller.refresh returns 401 when the service rejects (e.g. reuse detected)', async () => {
      const { controller } = makeController({
        authService: {
          refreshAccessToken: vi
            .fn()
            .mockRejectedValue(new Error('Refresh token reuse detected — session revoked')),
        } as any,
      });
      const res = mockResponse();

      await controller.refresh(
        { cookies: { refresh_token: 'x' } } as any,
        {} as any,
        res,
        '1.2.3.4',
        'agent'
      );

      expect(res.status).toHaveBeenCalledWith(401);
      expect(res.json).toHaveBeenCalledWith({ error: 'Invalid or expired refresh token' });
    });
  });
});

import 'reflect-metadata';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { ForbiddenException } from '@nestjs/common';
import { OAuthAppController } from './oauth-app.controller';
import { REQUIRE_PERMISSION_KEY } from '@postmill-ai/backend/services/auth/rbac/require-permission.decorator';
import { OrgRbacGuard } from '@postmill-ai/backend/services/auth/rbac/org-rbac.guard';

const mockOAuthService = {
  getApp: vi.fn(),
  createApp: vi.fn(),
  updateApp: vi.fn(),
  deleteApp: vi.fn(),
  rotateSecret: vi.fn(),
};

function buildGuardContext(user: any, orgId?: string) {
  return {
    getHandler: () => ({}),
    getClass: () => ({}),
    switchToHttp: () => ({
      getRequest: () => ({ user, orgId, path: '/user/oauth-app' }),
    }),
  } as any;
}

describe('OAuthAppController', () => {
  let controller: OAuthAppController;

  beforeEach(() => {
    vi.clearAllMocks();
    controller = new OAuthAppController(mockOAuthService as any);
  });

  // AUTH-02b: every route must carry the new oauth_apps:manage RBAC permission.
  describe('@RequirePermission metadata', () => {
    it.each([
      ['getApp', 'GET /'],
      ['createApp', 'POST /'],
      ['updateApp', 'PUT /'],
      ['deleteApp', 'DELETE /'],
      ['rotateSecret', 'POST /rotate-secret'],
    ])('%s (%s) is gated with oauth_apps:manage', (methodName) => {
      const metadata = Reflect.getMetadata(
        REQUIRE_PERMISSION_KEY,
        (controller as any)[methodName]
      );
      expect(metadata).toEqual({ resource: 'oauth_apps', action: 'manage' });
    });
  });

  describe('handler delegation', () => {
    const org = { id: 'org-123' } as any;

    it('getApp delegates to OAuthService.getApp', async () => {
      mockOAuthService.getApp.mockResolvedValue({ id: 'app-1' });
      const result = await controller.getApp(org);
      expect(mockOAuthService.getApp).toHaveBeenCalledWith('org-123');
      expect(result).toEqual({ id: 'app-1' });
    });

    it('createApp delegates to OAuthService.createApp', async () => {
      const dto = { name: 'My App', redirectUrl: 'https://example.com/cb' };
      mockOAuthService.createApp.mockResolvedValue({ id: 'app-2' });
      const result = await controller.createApp(org, dto as any);
      expect(mockOAuthService.createApp).toHaveBeenCalledWith('org-123', dto);
      expect(result).toEqual({ id: 'app-2' });
    });

    it('updateApp delegates to OAuthService.updateApp', async () => {
      const dto = { name: 'Updated' };
      mockOAuthService.updateApp.mockResolvedValue({ id: 'app-3' });
      const result = await controller.updateApp(org, dto as any);
      expect(mockOAuthService.updateApp).toHaveBeenCalledWith('org-123', dto);
      expect(result).toEqual({ id: 'app-3' });
    });

    it('deleteApp delegates to OAuthService.deleteApp', async () => {
      mockOAuthService.deleteApp.mockResolvedValue({ success: true });
      const result = await controller.deleteApp(org);
      expect(mockOAuthService.deleteApp).toHaveBeenCalledWith('org-123');
      expect(result).toEqual({ success: true });
    });

    it('rotateSecret delegates to OAuthService.rotateSecret', async () => {
      mockOAuthService.rotateSecret.mockResolvedValue({ clientSecret: 'secret' });
      const result = await controller.rotateSecret(org);
      expect(mockOAuthService.rotateSecret).toHaveBeenCalledWith('org-123');
      expect(result).toEqual({ clientSecret: 'secret' });
    });
  });

  // AUTH-02c acceptance: a member whose role does not include oauth_apps:manage
  // must be rejected with HTTP 403 before any controller handler runs.
  describe('RBAC enforcement', () => {
    const reflector = {
      getAllAndOverride: vi.fn(() => ({
        resource: 'oauth_apps',
        action: 'manage',
      })),
    } as any;

    const audit = { record: vi.fn().mockResolvedValue(undefined) } as any;

    it.each([
      ['getApp', 'GET /'],
      ['createApp', 'POST /'],
      ['updateApp', 'PUT /'],
      ['deleteApp', 'DELETE /'],
      ['rotateSecret', 'POST /rotate-secret'],
    ])(
      'rejects %s (%s) for a member lacking oauth_apps:manage with ForbiddenException',
      async (methodName) => {
        const rolesService = {
          getEffectivePermissions: vi.fn().mockResolvedValue({
            role: 'editor',
            permissions: ['posts:manage', 'media:manage', 'channels:manage'],
          }),
        };
        const guard = new OrgRbacGuard(reflector, rolesService as any, audit);

        await expect(
          guard.canActivate(
            buildGuardContext({ id: 'u-editor' }, 'org-123')
          )
        ).rejects.toThrow(ForbiddenException);
      }
    );

    it('allows a member with oauth_apps:manage', async () => {
      const rolesService = {
        getEffectivePermissions: vi.fn().mockResolvedValue({
          role: 'admin',
          permissions: ['oauth_apps:manage'],
        }),
      };
      const guard = new OrgRbacGuard(reflector, rolesService as any, audit);

      await expect(
        guard.canActivate(
          buildGuardContext({ id: 'u-admin' }, 'org-123')
        )
      ).resolves.toBe(true);
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Organization } from '@prisma/client';
import { HttpException } from '@nestjs/common';
import { ContentPackDailyCapError } from '@postmill-ai/nestjs-libraries/media/stock/content-packs/content-pack.interface';

import { FilesController } from './files.controller';

const org: Organization = { id: 'org-1' } as any;

function makeController() {
  const adapter = {
    readFile: vi.fn(),
  };
  const storageService = {
    getOrgStoragePublicPrefixes: vi.fn().mockResolvedValue(['https://app.example.com/uploads/']),
    resolveAdapterForFolder: vi.fn().mockResolvedValue(adapter),
  };
  const fileService = {
    getFolder: vi.fn().mockResolvedValue({ id: 'f1', organizationId: 'org-1' }),
    getFolderContents: vi.fn().mockResolvedValue({ count: 3 }),
    getByIds: vi.fn().mockResolvedValue([]),
    bulkMove: vi.fn().mockResolvedValue({ count: 0 }),
    importFromUrl: vi.fn().mockResolvedValue({ id: 'file-1' }),
    saveFile: vi.fn().mockResolvedValue({ id: 'file-1' }),
    bulkSave: vi.fn().mockResolvedValue([{ id: 'file-1' }, { id: 'file-2' }]),
    importFromPath: vi.fn(async (orgId: string, filePath: string, folderId?: string | null) => {
      const prefixes = await storageService.getOrgStoragePublicPrefixes(orgId);
      if (!prefixes.some((prefix: string) => filePath.startsWith(prefix))) {
        throw new HttpException('Invalid storage path', 400);
      }
      const resolvedAdapter = await storageService.resolveAdapterForFolder(folderId, orgId);
      try {
        const buffer = await resolvedAdapter.readFile(filePath);
        return { buffer, fileSize: buffer.length };
      } catch (err) {
        throw new HttpException('Storage object not found', 404);
      }
    }),
  };
  const contentPackCapabilityMap: Record<string, string> = {
    photo: 'photos',
    photos: 'photos',
    image: 'photos',
    vector: 'vectors',
    vectors: 'vectors',
    video: 'videos',
    videos: 'videos',
    sticker: 'stickers',
    stickers: 'stickers',
    icon: 'icons',
    icons: 'icons',
    audio: 'audio',
  };
  const stockMediaService = {
    importContentPackAsset: vi.fn(async (_orgId: string, source: string, downloadLocation: string, type?: string) => {
      const capability = contentPackCapabilityMap[(type || 'photos').toLowerCase()];
      if (!capability) {
        throw new Error(`Unsupported content pack type: ${type}`);
      }
      return { url: 'https://cdn/licensed.jpg', capability };
    }),
    triggerDownload: vi.fn().mockResolvedValue(undefined),
  };
  const resolution = {
    listManifests: vi.fn().mockReturnValue([{ providerId: 'magnific' }]),
  };
  const ctrl = new FilesController(
    fileService as any,
    storageService as any,
    stockMediaService as any,
    resolution as any,
  );
  return { ctrl, fileService, storageService, adapter, stockMediaService, resolution };
}

beforeEach(() => vi.clearAllMocks());

describe('FilesController — tenant isolation & content-pack mint', () => {
  describe('1.1 getFolderContents is org-scoped', () => {
    it('validates folder ownership before returning contents', async () => {
      const { ctrl, fileService } = makeController();

      const result = await ctrl.getFolderContents(org, 'folder-b');

      expect(fileService.getFolder).toHaveBeenCalledWith('org-1', 'folder-b');
      expect(fileService.getFolderContents).toHaveBeenCalledWith('org-1', 'folder-b');
      expect(result).toEqual({ count: 3 });
    });

    it('propagates the 404 for a folder the org does not own', async () => {
      const { ctrl, fileService } = makeController();
      fileService.getFolder.mockRejectedValue(new HttpException('Folder not found', 404));

      await expect(ctrl.getFolderContents(org, 'folder-b')).rejects.toThrow('Folder not found');
      expect(fileService.getFolderContents).not.toHaveBeenCalled();
    });
  });

  describe('1.2 bulkMove restricts to owned ids', () => {
    it('moves only ids the org owns (foreign ids drop out → 0 rows)', async () => {
      const { ctrl, fileService } = makeController();
      // requested [own-1, foreign-1]; org only owns own-1
      fileService.getByIds.mockResolvedValue([{ id: 'own-1' }]);

      await ctrl.bulkMove(org, { ids: ['own-1', 'foreign-1'], folderId: 'dest' } as any);

      expect(fileService.getByIds).toHaveBeenCalledWith('org-1', ['own-1', 'foreign-1']);
      expect(fileService.bulkMove).toHaveBeenCalledWith('org-1', ['own-1'], 'dest');
    });

    it('passes an empty id set (0 rows) when none are owned', async () => {
      const { ctrl, fileService } = makeController();
      fileService.getByIds.mockResolvedValue([]);

      await ctrl.bulkMove(org, { ids: ['foreign-1'], folderId: null } as any);

      expect(fileService.bulkMove).toHaveBeenCalledWith('org-1', [], null);
    });
  });

  describe('0.4 content-pack singular→plural capability mapping', () => {
    const body = (type: string) => ({
      url: '',
      name: 'x',
      source: 'magnific',
      downloadLocation: 'item-123',
      type,
    });

    it.each([
      ['photo', 'photos'],
      ['image', 'photos'],
      ['vector', 'vectors'],
      ['video', 'videos'],
      ['sticker', 'stickers'],
      ['icon', 'icons'],
      ['audio', 'audio'],
    ])('maps client type "%s" → capability "%s"', async (clientType, expected) => {
      const { ctrl, stockMediaService } = makeController();

      await ctrl.importFromUrl(org, body(clientType) as any);

      expect(stockMediaService.importContentPackAsset).toHaveBeenCalledWith(
        'org-1',
        'magnific',
        'item-123',
        clientType,
      );
    });

    it('rejects an unknown type with 400 (no silent default)', async () => {
      const { ctrl, stockMediaService } = makeController();

      await expect(ctrl.importFromUrl(org, body('bogus') as any)).rejects.toMatchObject({
        status: 400,
      });
      expect(stockMediaService.importContentPackAsset).not.toHaveBeenCalled();
    });

    it('maps a daily-cap error to 402', async () => {
      const { ctrl, stockMediaService } = makeController();
      stockMediaService.importContentPackAsset.mockRejectedValue(
        new ContentPackDailyCapError('cap reached'),
      );

      await expect(ctrl.importFromUrl(org, body('photo') as any)).rejects.toMatchObject({
        status: 402,
      });
    });

    it('returns a generic 502 (not raw provider text) on a mint failure', async () => {
      const { ctrl, stockMediaService } = makeController();
      stockMediaService.importContentPackAsset.mockRejectedValue(
        new Error('upstream 500 <html>secret</html>'),
      );

      await expect(ctrl.importFromUrl(org, body('photo') as any)).rejects.toMatchObject({
        status: 502,
        message: 'Could not retrieve the licensed asset',
      });
    });
  });

  describe('1.4 path ownership validation for save-media', () => {
    it('rejects a foreign-origin URL with 400', async () => {
      const { ctrl, storageService, fileService } = makeController();

      await expect(
        ctrl.saveMedia(org, { name: 'name', path: 'https://evil.com/uploads/x.png', originalName: 'x.png' } as any),
      ).rejects.toMatchObject({ status: 400, message: 'Invalid storage path' });

      expect(storageService.resolveAdapterForFolder).not.toHaveBeenCalled();
      expect(fileService.saveFile).not.toHaveBeenCalled();
    });

    it('rejects a matching-prefix but non-existent object with 404', async () => {
      const { ctrl, adapter, storageService, fileService } = makeController();
      adapter.readFile.mockRejectedValue(new Error('NoSuchKey'));

      await expect(
        ctrl.saveMedia(org, { name: 'name', path: 'https://app.example.com/uploads/missing.png', originalName: 'missing.png' } as any),
      ).rejects.toMatchObject({ status: 404, message: 'Storage object not found' });

      expect(storageService.resolveAdapterForFolder).toHaveBeenCalledWith(undefined, 'org-1');
      expect(fileService.saveFile).not.toHaveBeenCalled();
    });

    it('accepts a valid org-owned object and persists it', async () => {
      const { ctrl, adapter, storageService, fileService } = makeController();
      adapter.readFile.mockResolvedValue(Buffer.from('bytes'));

      const result = await ctrl.saveMedia(
        org,
        { name: 'saved.png', path: 'https://app.example.com/uploads/owned.png', originalName: 'owned.png' } as any,
      );

      expect(storageService.resolveAdapterForFolder).toHaveBeenCalledWith(undefined, 'org-1');
      expect(adapter.readFile).toHaveBeenCalledWith('https://app.example.com/uploads/owned.png');
      expect(fileService.saveFile).toHaveBeenCalledWith(
        'org-1',
        'saved.png',
        'https://app.example.com/uploads/owned.png',
        'owned.png',
        undefined,
        5,
      );
      expect(result).toEqual({ id: 'file-1' });
    });
  });

  describe('1.4 path ownership validation for bulk/save', () => {
    it('rejects the batch if any path is foreign', async () => {
      const { ctrl, fileService } = makeController();

      await expect(
        ctrl.bulkSaveFiles(org, {
          items: [
            { name: 'a.png', path: 'https://app.example.com/uploads/a.png' },
            { name: 'b.png', path: 'https://evil.com/uploads/b.png' },
          ],
        } as any),
      ).rejects.toMatchObject({ status: 400, message: 'Invalid storage path' });

      expect(fileService.bulkSave).not.toHaveBeenCalled();
    });

    it('rejects the batch if any object does not exist', async () => {
      const { ctrl, adapter, fileService } = makeController();
      adapter.readFile
        .mockResolvedValueOnce(Buffer.from('bytes'))
        .mockRejectedValueOnce(new Error('NoSuchKey'));

      await expect(
        ctrl.bulkSaveFiles(org, {
          items: [
            { name: 'a.png', path: 'https://app.example.com/uploads/a.png' },
            { name: 'b.png', path: 'https://app.example.com/uploads/b.png' },
          ],
        } as any),
      ).rejects.toMatchObject({ status: 404, message: 'Storage object not found' });

      expect(fileService.bulkSave).not.toHaveBeenCalled();
    });

    it('saves the batch when every path is valid and reachable', async () => {
      const { ctrl, adapter, fileService } = makeController();
      adapter.readFile.mockResolvedValue(Buffer.from('bytes'));

      const result = await ctrl.bulkSaveFiles(org, {
        items: [
          { name: 'a.png', path: 'https://app.example.com/uploads/a.png' },
          { name: 'b.png', path: 'https://app.example.com/uploads/b.png' },
        ],
      } as any);

      expect(adapter.readFile).toHaveBeenCalledTimes(2);
      expect(fileService.bulkSave).toHaveBeenCalledWith('org-1', [
        { name: 'a.png', path: 'https://app.example.com/uploads/a.png', fileSize: 5 },
        { name: 'b.png', path: 'https://app.example.com/uploads/b.png', fileSize: 5 },
      ]);
      expect(result).toEqual([{ id: 'file-1' }, { id: 'file-2' }]);
    });
  });
});

